insert into public.branches (code, name_ar, address, payment_methods, managers, price_list_id, sort) values ('tanta1', 'طنطا ١ - الاستاد', 'برج الأطباء، بجوار مستشفى كنانة، أعلى ملفوف وكيتي، الدور السادس', array['Visa', 'Cash']::text[], array['Menna Ajlan', 'Haidy', 'Esraa']::text[], (select id from public.price_lists where code = 'standard'), 0);
insert into public.branch_policies (branch_id, request_window_days, same_day_always_request, auto_confirm_weekdays, allow_overlap, booking_rules) values ((select id from public.branches where code = 'tanta1'), 1, false, array[0]::smallint[], true, array['د. هبة غنيم و د. بسنت عوارة: أي معاد ليهم حتى لو النهاردة أو بكرة، يتبعت للفرع بحالة Status: Open، باستثناء يوم الجمعة — مواعيد يوم السبت بنأكدها لأن الفرع إجازة الجمعة (يوم الخميس بالليل الفرع بيبعت المواعيد المتاحة يوم السبت) وبنبعت للفرع Notice هم يأكدوا بيها. لو الدكتورة هي اللي طلبت إننا نأكد المعاد، بنأكد.', 'د. إسراء عبدالحميد، د. نهى محمد عبدالله، د. نيرمين عادل: ممكن نحجز في نفس اليوم أو لبكرة بحالة Status: Confirm، وبنبعت للفرع Notice فقط، من غير ما ننتظر تأكيد معاد منهم.', 'د. هبة غنيم و د. بسنت عوارة مش بيشتغلوا لرجالة.', 'د. بسنت عوارة مش بتستقبل أريات صغيرة (زي موستاش بس أو أندر أرم بس) — بنحوّلهم على باقي الدكاترة، لكن مش بنحوّل الأريات الصغيرة على د. هبة غنيم.', 'لما الحجز بيتقفل، بيتبعت Update بالحالة دي.', 'أي سيرفيس غير الليزر أو الكشوفات بيتبعت حتى لو الحجز مقفول، واحنا بنكلمهم.', 'أي تأكيد حجز بيتم من خلال الكول سنتر، لازم يتبعت بالبيانات كاملة: اتأكد إمتى، وهيعمل أريا إيه.', 'أي حد محتاج تواصل من الفرع، برضو لازم البيانات تتبعت كاملة، والتواصل بخصوص إيه.']::text[]);
