insert into public.branches (code, name_ar, address, payment_methods, managers, price_list_id, sort) values ('tanta2', 'طنطا ٢ - سعيد', 'عمارة ٤٨ زهرة السعيد، شارع سعيد، بجوار فتح الله، أعلى راية شوب، الدور الأول', array['Visa', 'Cash']::text[], '{}'::text[], (select id from public.price_lists where code = 'standard'), 1);
insert into public.branch_policies (branch_id, request_window_days, same_day_always_request, auto_confirm_weekdays, allow_overlap, booking_rules) values ((select id from public.branches where code = 'tanta2'), 1, true, '{}'::smallint[], true, array['لو الحالة عايزة تيجي في نفس اليوم: بتتبعت على الجروب، ونشوف لو متاح — بنكلمها، أو بنأجل معادها ليوم تاني.', 'لو الحالة عايزة تيجي يوم تاني: بتتبعت على الواتساب بحالة Open، واحنا بنعمل معاها Confirm من غير ما ننتظر الفرع.', 'أقصى حجوزات: يفضّل لو الـ Open وصل لـ ١٠٠ في شفتات الفل داي، ما نزودش عليه — ممكن نرحّل لأيام تانية.', 'لو الحالة عايزة تيجي مع دكتورة معينة واليوم كومبليت: نبعتها على الجروب أو نعرض عليها يوم تاني الدكتورة موجودة فيه. بلاش نرشح دكتورة تانية إلا لو العميلة هي اللي اختارت.', 'شفتات الصبح أيام الاتنين والتلات والخميس: آخر استقبال لحالات الليزر الساعة ٢.', 'لو الحالة متأخرة عن معادها: تتبعت على الجروب نشوف لو متاح تيجي أو لأ.']::text[]);
