insert into public.branch_policies (branch_id, request_window_days, same_day_always_request, auto_confirm_weekdays, allow_overlap, booking_rules) values ((select id from public.branches where code = 'newcairo'), 1, false, '{}'::smallint[], true, array['كل الدكاترة بيشتغلوا للرجالة عادي.', 'أي حجز لـ د. بسنت عوارة يتبعت بحالة Open بالبيانات كاملة، واحنا هنعمل Confirm من عندنا.', 'أي حالة عمومًا تتواصل مع الكول سنتر، تتبعتلنا على الجروب، وياريت يكون معاها البيانات كاملة وإيه استفسارها.', '⚠️ مواعيد الدكاترة والأسعار في الفرع ده مختلفة عن باقي الفروع — لازم نتأكد منها كل مرة علشان ميحصلش لبس مع العميلة.', 'مواعيد الدكاترة هنا مش ثابتة زي باقي الفروع، وبتتحدث بـ Update بشكل دوري.']::text[]);
