insert into public.kb_articles (slug, kind, title, body, sort) values ('service:derma_consult', 'service', 'كشوفات الجلدية والشعر (Consultation)', '{"id":"derma_consult","name":"كشوفات الجلدية والشعر (Consultation)","branch":null,"summary":"كشف الجلدية هو البداية المناسبة لتقييم مشاكل البشرة أو الشعر أو الأظافر. الدكتور بيبدأ بأخذ تاريخ الحالة وفحصها، وقد يستخدم الديرماسكوب حسب الحالة، وهو أداة مكبرة بتساعد في رؤية تفاصيل الجلد أو فروة الرأس بشكل أوضح.","details":[["مشاكل البشرة","حب الشباب وآثاره، الكلف والتصبغات، الإكزيما، الصدفية، الوردية، الحساسية، الفطريات، الثآليل (السنط)، البهاق، والشامات أو أي تغيرات جديدة في الجلد"],["مشاكل الشعر وفروة الرأس","تساقط الشعر، الصلع الوراثي، الثعلبة، القشرة والتهاب فروة الرأس، وضعف وتقصف الشعر"],["الكشف بيشمل","معرفة تاريخ المشكلة والأعراض والأدوية المستخدمة، فحص البشرة أو الشعر وفروة الرأس، استخدام الديرماسكوب حسب الحالة، وقد يطلب الدكتور تحاليل عند الحاجة (زي Ferritin أو Thyroid tests أو بعض الهرمونات حسب الحالة). التحاليل مش جزء ثابت من كل كشف، والدكتور هو اللي بيحدد هل الحالة محتاجة تحاليل"],["أنواع الكشف","كشف بشرة (أول مرة)، متابعة بشرة، كشف شعر (أول مرة)، متابعة شعر، وكشف بشرة وشعر معًا في نفس الزيارة"],["المتابعة","غالبًا بعد 4-6 أسابيع، لكن الموعد بيختلف حسب الحالة وخطة العلاج اللي يحددها الدكتور"]],"products":[],"booking":["الكشف مدفوع دايمًا، وممنوع نقول إنه مجاني إلا لو فيه عرض ساري ومذكور في مكتب الأسعار","كشف البشرة والشعر معًا له سعر مختلف عن كشف تخصص واحد","في كفر الشيخ مع د. خلود فيروز أو د. شيماء حسن فيه سعر خاص حسب سياسة الأسعار الحالية؛ راجع مكتب الأسعار قبل تأكيد الحجز"],"care":[["قبل","يفضل العميل يجيب أي تحاليل أو روشتات أو أدوية بيستخدمها حاليًا، ولو فيه صور أو تقارير طبية سابقة يفضل إحضارها"],["قبل","لو الكشف للبشرة أو الوجه، يفضل الحضور بدون مكياج قدر الإمكان. لو للشعر، يفضل عدم وضع زيوت أو جيل أو منتجات تصفيف قبل الكشف"]],"say":[["الكشف بيبقى إزاي؟","الدكتور بيسمع منك الأول عن المشكلة وتاريخها، وبعدها بيفحص البشرة أو الشعر، وممكن يستخدم الديرماسكوب، عدسة مكبرة بتوضح تفاصيل مش دايمًا بتبان بالعين وغير مؤلم"],["الكشف مجاني؟","الكشف بسعر محدد، ولو فيه عرض ساري حاليًا هقولك عليه"],["عندي حبوب كتير، أعمل إيه؟","الحبوب ليها أسباب وأنواع مختلفة، فالأفضل تعملي كشف علشان الدكتور يقيّم الحالة ويحدد العلاج المناسب"],["هبعتلك صورة، قولي ده إيه","أقدر أسجل لحضرتك الكشف، لكن التشخيص محتاج تقييم الدكتور للحالة بشكل مباشر، والصورة لوحدها مش كفاية للتشخيص"],["شعري بيقع جامد","تساقط الشعر له أسباب مختلفة، والدكتور هيكشف على الشعر وفروة الرأس ويحدد السبب، وممكن يطلب تحاليل لو شايف إنها مطلوبة"]],"escalate":"طفح منتشر ومفاجئ مع تورم في الوجه أو الشفايف، صعوبة في التنفس، أو أعراض حساسية شديدة — دي ممكن تكون حالة طارئة، ووجّه العميل للرعاية الطبية الطارئة فورًا بدل الاكتفاء بحجز كشف. ولو العميل بيذكر شامة فيها تغير سريع في الحجم أو الشكل، تغير واضح في اللون، نزيف متكرر بدون سبب واضح، أو قرحة لا تلتئم، يتم حجز كشف جلدية في أقرب موعد متاح وتسجيل وصف العميل بوضوح","review":["عميل سأل: الكشف مجاني؟ ترد تقول إيه؟","عميل بعت صورة وطلب كريم، ترد تقول إيه؟","عميل ذكر شامة بتغير لونها بسرعة، تعمل إيه؟"]}'::jsonb, 0);
insert into public.kb_articles (slug, kind, title, body, sort) values ('service:laser_hair', 'service', 'ليزر إزالة الشعر (Laser Hair Removal)', '{"id":"laser_hair","name":"ليزر إزالة الشعر (Laser Hair Removal)","branch":null,"summary":"ليزر إزالة الشعر بيستهدف بصيلة الشعر بطاقة ضوئية محددة، وبيضعفها تدريجيًا مع الجلسات، فبيقل نمو الشعر بشكل ملحوظ، والشعر اللي بيظهر بيكون غالبًا أرفع وأفتح. عدد الجلسات والنتيجة بتختلف حسب المنطقة والهرمونات ولون وكثافة الشعر واستجابة كل حالة، والطبيب هو اللي بيحدد المناسب.","details":[["الجهاز المستخدم","Cynosure Elite Plus: Alexandrite 755 nm للبشرة الفاتحة والقمحية، Nd:YAG 1064 nm للبشرة السمراء والغامقة، وZimmer Cooling للتبريد بالهواء البارد أثناء الجلسة"],["دواعي الاستخدام","تقليل نمو الشعر الزائد في الوجه والجسم، تقليل كثافة الشعر تدريجيًا مع الجلسات، وتحسين ملمس ومظهر الشعر المتبقي بحيث يكون أرفع وأفتح مع الوقت"],["المناطق المتاحة للسيدات","Mustache, Face, Neck, Under-Arm, Bikini, Half Arms, Full Arms, Half Legs Upper, Half Legs Lower, Full Legs, Full Body Without Back & Belly, Full Body"],["المناطق المتاحة للرجال","Beard Shaping, Half Face, Under-Arms, Arms, Legs, Chest, Back, Full Body"],["عدد الجلسات","من 6 لـ 8 جلسات في المتوسط، والعدد بيختلف حسب المنطقة والهرمونات ولون الشعر وكثافته وسُمكه واستجابة الحالة"],["المسافة بين الجلسات","Face: من 3 لـ 4 أسابيع. Body: من 4 لـ 6 أسابيع"],["مدة الجلسة","المناطق الصغيرة من حوالي 10 دقائق، والـ Full Body ممكن توصل لحوالي ساعة ونصف"],["الإحساس أثناء الجلسة","زي شكة استك خفيفة مع تبريد، ودرجة الإحساس بتختلف حسب المنطقة وحساسية كل شخص"],["مش مناسب لـ","الحمل، الرضاعة حسب تقييم الطبيب، وجود التهاب أو عدوى جلدية نشطة في المنطقة أو جروح مفتوحة، حروق أو تعرض شديد وحديث للشمس، بعض الأدوية اللي بتزود حساسية الجلد للضوء، وبعض الحالات الجلدية المزمنة غير المستقرة"]],"products":[],"booking":["Single Session: جلسة واحدة، ولكل منطقة سعرها","3 Sessions Package: 3 جلسات لنفس المنطقة بسعر أفضل (الباكدج لنفس المنطقة فقط)","Prepaid Pulses: باكدج نبضات مدفوعة مقدمًا من 2,000 لحد 20,000 نبضة","Per Pulse: الحساب بالنبضة، وسعر النبضة للسيدات يختلف عن الرجال","Add-ons: Protective Tip، أو Protective Tip + Gown","⚠️ Laser للرجال: لازم التأكد إن الدكتور بيعمل للرجال والمنطقة المطلوبة قبل تأكيد الحجز","Full Body للرجال: مع Doctor Male فقط","Full Body للسيدات: Protective Tip + Gown مجانًا حسب السياسة الحالية، ولو مش شاملينهم يتم إضافتهم على الفاتورة حسب الـ Price List","⚠️ ممنوع نقول للعميل: «الشعر هيروح نهائي» / «الشعر مش هيرجع تاني» / «مش هتحتاج جلسات تاني» / «النتيجة مضمونة 100%» / «مش هتحتاج Retouch» / «متقلقش من الشمس» / «أي دكتور ينفع يعمل Laser للرجالة» / أو نقول إن حالة معينة ينفع تعمل ليزر من غير تقييم الطبيب"],"care":[["قبل","حلاقة المنطقة بالموس قبل الجلسة بيوم تقريبًا، وعدم إزالة الشعر بالشمع أو الحلاوة أو الملقط"],["قبل","تجنب التعرض للشمس والسمار الشديد قبل الجلسة، والحضور والجلد نظيف من الكريمات والزيوت ومزيل العرق في منطقة العلاج"],["قبل","التوقف عن الكريمات المقشرة أو الحساسة للضوء (زي Retinol) حسب توجيه الطبيب، وإخبار الطبيب بأي أدوية بتزود حساسية الجلد للضوء أو أي التهاب/مشكلة جلدية في المنطقة"],["بعد","ممكن يظهر احمرار أو تهيج بسيط ومؤقت، استخدام Sunblock بانتظام وتجنب التعرض المباشر للشمس"],["بعد","تجنب Sauna والمياه شديدة السخونة لمدة 48 ساعة، وعدم حك أو خدش المنطقة المعالجة"],["بعد","تجنب المقشرات والعطور والمنتجات القوية على المنطقة لعدة أيام أو حسب تعليمات الطبيب"],["البحر","لو العميل سأل عن البحر: يفضل الانتظار 48 ساعة على الأقل، مع تجنب الشمس المباشرة واستخدام Sunblock مناسب"]],"say":[["الشعر هيروح نهائي؟","الشعر بيقل بشكل كبير جدًا مع الجلسات، والشعر اللي بيفضل بيكون غالبًا أرفع وأفتح، وممكن تحتاجي جلسات Retouch من وقت للتاني حسب الحالة"],["أنا سمراء، ينفع أعمل ليزر؟","أيوه، الجهاز عندنا فيه Nd:YAG 1064 nm المناسب للبشرة السمراء والغامقة، والطبيب بيحدد الإعداد المناسب حسب لون البشرة وحالة الشعر"],["إيه أوفر طريقة؟","لو هتعملي أكتر من منطقة، ممكن باكدج الـ Prepaid Pulses يكون أوفر حسب استخدامك، ولو منطقة واحدة، ممكن باكدج الـ 3 Sessions يكون أنسب"],["أنا راجل، ينفع أحجز؟","أيوه، ممكن نسجل لحضرتك طلب، بس الأول بنتأكد إن الدكتور بيعمل Laser للرجالة والمنطقة المطلوبة"],["الليزر بيوجع؟","الإحساس بيكون زي شكة استك خفيفة مع تبريد، ودرجة الإحساس بتختلف حسب المنطقة وحساسية كل شخص"],["الجلسة بتاخد وقت قد إيه؟","المناطق الصغيرة ممكن تبدأ من حوالي 10 دقايق، والـ Full Body ممكن يوصل لحوالي ساعة ونص"],["ينفع أنزل البحر بعد الجلسة؟","يفضل تستني 48 ساعة على الأقل، وتبعدي عن الشمس المباشرة وتستخدمي Sunblock كويس"]],"escalate":"تهيج شديد أو أعراض غير معتادة بعد الجلسة، أو حروق أو فقاقيع أو تغيّر واضح في لون الجلد","review":["إيه اسم الجهاز المستخدم في الليزر، وإيه الفرق بين الـ Alexandrite والـ Nd:YAG؟","عميل راجل عايز يحجز Full Body ليزر، إيه أول حاجة لازم تتأكد منها؟","إمتى الـ Protective Tip والـ Gown بيبقوا مجانًا للسيدات؟","لو العميلة سألت عن نزول البحر بعد الجلسة، ترد تقول إيه؟"]}'::jsonb, 1);
insert into public.kb_articles (slug, kind, title, body, sort) values ('service:fractional', 'service', 'الفراكشنال ليزر CO2 (Fractional Laser CO2)', '{"id":"fractional","name":"الفراكشنال ليزر CO2 (Fractional Laser CO2)","branch":"متاح في القاهرة الجديدة، وطنطا ٢ - سعيد، والمنصورة فقط","summary":"الفراكشنال CO2 بيعمل فتحات مجهرية ومحكومة في الجلد، فبيحفّز الجلد إنه يجدد نفسه وينتج كولاجين جديد. من أقوى العلاجات لتحسين آثار الحبوب والندبات والملمس والتجاعيد الرفيعة، لكن لازم العميل يعرف إن له فترة تعافي حقيقية بعد الجلسة.","details":[["دواعي الاستخدام","آثار الحبوب الغائرة، المسام الواسعة، التجاعيد الرفيعة، منطقة تحت العين، الندبات (صغيرة/متوسطة/كبيرة حسب تقييم الدكتور)، الشقوق الجلدية، تجديد وتحسين ملمس البشرة، وإزالة الزوائد الجلدية Skin Tags"],["عدد الجلسات","غالبًا 3-5 جلسات، الفاصل بين الجلسات 4-8 أسابيع حسب تقييم الدكتور واستجابة البشرة. الزوائد الجلدية غالبًا جلسة واحدة حسب العدد والحالة"],["مدة الجلسة","حوالي ساعة، منها تقريبًا 30-45 دقيقة كريم مخدر قبل الإجراء"],["فترة التعافي","احمرار وورم ممكن يستمروا حوالي 3-7 أيام، وبعد كده ممكن يحصل قشر وتغيّر مؤقت في لون الجلد لحد ما البشرة تتجدد. لازم العميل يعرف فترة التعافي قبل الحجز عشان يختار موعد مناسب ومفيهوش مناسبات مهمة"],["النتيجة","بتبدأ تظهر بعد مرحلة التقشير والتعافي، والتحسن بيستمر تدريجيًا خلال 3-6 شهور، ودرجة التحسن بتختلف حسب الحالة وعمق الآثار واستجابة البشرة"],["الجلسات المتاحة","الوجه: Face / Face + Neck / Under Eye. الندبات: Small / Medium / Large (الحجم بيتحدد بواسطة الدكتور). Skin Tags: 1 Skin Tag / 2-5 / 6-10 / 11-20"],["مش مناسب لـ / لازم تتراجع مع الدكتور","الحمل، حروق أو تعرض قوي للشمس، وجود التهاب أو عدوى نشطة بالجلد، تاريخ مرضي أو قابلية لتكوين Keloid، استخدام Accutane/Roaccutane حاليًا أو في الفترة الأخيرة، وجود Active Herpes أو تاريخ متكرر يحتاج تقييم، والبشرة السمراء أو الداكنة (لتقييم احتمالية التصبغات ووضع التحضير المناسب)"]],"products":[],"booking":["⚠️ متاح فقط في فروع: القاهرة الجديدة، طنطا ٢ - سعيد، والمنصورة — لو العميل من فرع تاني، وضّح إنه مش متاح في فرعه","لازم العميل يعرف قبل الحجز إن فيه احمرار وتقشير متوقعين لمدة حوالي 5-7 أيام","لا يتم التعامل مع Roaccutane / Accutane كحالة عادية؛ يتم تسجيله وإبلاغ الدكتور","لو الجلسة هتتعمل مع Exosomes أو PRP أو Mesotherapy، يتم إضافة سعر المادة على سعر جلسة الـ Fractional CO2","بالنسبة للـ Skin Tags، السعر حسب عدد الزوائد، والدكتور بيحدد إنها Skin Tags فعلًا أثناء الكشف","⚠️ الـ Agent لا يقرر إن العميل مناسب للجلسة أو لا؛ دوره تسجيل المعلومة (رواكيوتان، هربس، حمل...) وتحويلها للدكتور عند الحاجة"],"care":[["قبل","اسأل العميل إذا كان بياخد Accutane / Roaccutane (رواكيوتان) حاليًا أو أخده في الفترة الأخيرة، وسجل المعلومة للدكتور"],["قبل","اسأل عن وجود تاريخ للإصابة بـ Herpes وسجل المعلومة للدكتور"],["قبل","البشرة السمراء أو الداكنة تحتاج تقييم وتحضير مناسب قبل الجلسة"],["قبل","لازم يكون العميل عارف فترة التعافي قبل اختيار الموعد، وتجنب الحجز قبل مناسبة مهمة مباشرة بسبب الاحمرار والتقشير المتوقع"],["بعد","استخدام كريمات الترميم اللي وصفها الدكتور، وممنوع إزالة أو شد القشر باليد"],["بعد","ممنوع التعرض المباشر للشمس، مع الالتزام بتعليمات الدكتور واستخدام Sunblock"],["بعد","يفضل تجنب المكياج لحوالي أسبوع أو حسب تعليمات الدكتور، وممنوع استخدام Retinol أو Acids إلا بعد السماح من الدكتور"]],"say":[["هقعد في البيت قد إيه؟","غالبًا من 5-7 أيام، والوجه ممكن يكون محمر ويحصل تقشير، فالأفضل اختيار موعد مفيهوش مناسبات قريبة"],["هيشيل آثار الحبوب خالص؟","الفراكشنال بيحسن آثار الحبوب والندبات بشكل واضح، لكن درجة التحسن بتختلف حسب عمق الآثار والحالة، والدكتور يقدر يحدد التوقعات المناسبة بعد التقييم"],["عندي زوائد جلدية في الرقبة، ينفع تتشال؟","ممكن يتم التعامل مع الـ Skin Tags، والسعر بيكون حسب العدد، والدكتور بيقيّمها أثناء الكشف ويتأكد من طبيعتها قبل الإجراء"],["أعمله في الصيف؟","ممكن حسب تقييم الدكتور وقدرة العميل على الالتزام بتعليمات الحماية من الشمس، وناس كتير بتفضّل عمله في الخريف والشتاء بسبب صعوبة الالتزام بالشمس في الصيف"]],"escalate":"صديد، سخونية أو حرارة واضحة، ألم بيزيد بدل ما يقل، فقاقيع تشبه الـ Herpes، أو احمرار شديد ومستمر بعد فترة التعافي المتوقعة أو بشكل غير طبيعي","review":["فترة التعافي المتوقعة للـ CO2 قد إيه؟","ليه لازم توضح فترة التعافي قبل الحجز؟","اذكر دواء لازم تسأل عنه قبل الجلسة.","لو اتعملت مع Exosomes أو PRP أو Mesotherapy، السعر بيتحسب إزاي؟"]}'::jsonb, 2);
insert into public.kb_articles (slug, kind, title, body, sort) values ('service:laser_vascular', 'service', 'ليزر الشعيرات الدموية (Vascular Laser)', '{"id":"laser_vascular","name":"ليزر الشعيرات الدموية (Vascular Laser)","branch":null,"summary":"نفس جهاز Cynosure Elite+ المستخدم في إزالة الشعر، بس بإعدادات مخصصة للشعيرات الدموية. الليزر بيستهدف الشعيرات الدموية الصغيرة الظاهرة في الجلد، وبيساعد على تقليلها تدريجيًا بعد الجلسة.","details":[["دواعي الاستخدام","الشعيرات الدموية الظاهرة تحت العين، الشعيرات الرفيعة في الرجلين، بعض الشعيرات الظاهرة في الوجه، والشعيرات السطحية الصغيرة حسب تقييم الدكتور. الدوالي الكبيرة أو الحالات غير الواضحة لازم يشوفها الدكتور الأول قبل حجز الجلسة"],["عدد الجلسات","غالبًا من جلسة لـ 3 جلسات، بيختلف حسب الحالة والاستجابة، والدكتور بيحدد العدد المناسب بعد التقييم"],["الجهاز","Cynosure Elite+، نفس جهاز Laser Hair Removal، لكن بإعدادات مختلفة مخصصة للأوعية والشعيرات الدموية، وسعر النبضة مختلف عن سعر نبضة إزالة الشعر"],["النتيجة","مش بتظهر بالضرورة فورًا، الشعيرات بتبدأ تخف تدريجيًا خلال الأسابيع التالية للجلسة، وممكن تحتاج الحالة لأكتر من جلسة حسب الاستجابة"],["مش مناسب لـ / لازم تتراجع مع الدكتور","الحمل، وجود حرق أو تعرض قوي للشمس في المنطقة، وجود دوالي كبيرة، وأي حالة وعائية غير واضحة أو غير مشخصة — الدوالي الكبيرة مش معناها إن العميل ممنوع نهائيًا، لكن لازم الدكتور يشوف الحالة الأول"]],"products":[],"booking":["بالنبضة: الحجز حسب عدد الـ Pulses","جلسة للمنطقة: Under Eye / Lower Leg حتى 400 نبضة / Upper Leg حتى 500 نبضة","Pulse Package: باكدجات بعدد نبضات حسب المتاح (عدد النبضات الفعلي بيتحدد حسب المنطقة والحالة أثناء الجلسة)","نفس جهاز إزالة الشعر، لكن بإعدادات مختلفة مخصصة للشعيرات الدموية، وسعر الـ Pulse مختلف عن سعر Pulse إزالة الشعر","⚠️ الدوالي الكبيرة لازم الدكتور يشوفها الأول قبل تأكيد حجز جلسة الليزر","السعر موحد في جميع الفروع، بما فيها التجمع"],"care":[["قبل","تجنب التعرض للشمس أو حدوث Sun Tan لمدة حوالي أسبوعين قبل الجلسة"],["قبل","لازم إبلاغ الدكتور لو العميل عنده دوالي كبيرة أو مشكلة وعائية واضحة في المنطقة، ولو الحالة غير واضحة ما يتمش تأكيد جلسة ليزر قبل تقييم الدكتور"],["بعد","ممكن يحصل احمرار بسيط أو تغير مؤقت للون المنطقة مكان الشعيرات لعدة أيام"],["بعد","تجنب الشمس المباشرة والـ Sauna والمياه شديدة السخونة والرياضة العنيفة لمدة حوالي 48 ساعة، والالتزام باستخدام Sunblock حسب تعليمات الدكتور"]],"say":[["ده نفس ليزر إزالة الشعر؟","نفس جهاز Cynosure Elite+، لكن بنستخدم إعدادات مختلفة ومخصصة للشعيرات الدموية"],["عندي دوالي في رجلي، ينفع أعمل الجلسة؟","لو الدوالي كبيرة، لازم الدكتور يشوفها الأول ويحدد الأنسب للحالة. تحبي أحجزلك كشف عند الدكتور؟"],["هتختفي من أول جلسة؟","الشعيرات بتبدأ تخف تدريجيًا خلال الأسابيع بعد الجلسة، وممكن تحتاج الحالة لأكتر من جلسة حسب الاستجابة"],["هل ممكن أعملها وأنا متعرضة للشمس؟","لازم نتجنب الـ Sun Tan قبل الجلسة بحوالي أسبوعين، والدكتور يحدد إذا البشرة مناسبة للجلسة"]],"escalate":"حروق واضحة، ظهور فقاقيع، ألم شديد أو بيزيد، أو تورم واضح أو متزايد في الرجل — أي عرض شديد أو غير متوقع بيتحول للدكتور فورًا من غير تطمين العميل","review":["عميلة عندها دوالي كبيرة وعايزة تحجز جلسة ليزر، تعمل إيه؟","إيه الفرق بين إعدادات ليزر الشعيرات وليزر إزالة الشعر؟","إيه المدة اللي لازم تجنب فيها الشمس قبل الجلسة؟"]}'::jsonb, 3);
insert into public.kb_articles (slug, kind, title, body, sort) values ('service:filler_face', 'service', 'فيلر الوجه (Facial Filler)', '{"id":"filler_face","name":"فيلر الوجه (Facial Filler)","branch":null,"summary":"الفيلر هو مادة مالئة، غالبًا Hyaluronic Acid، بتتحقن تحت الجلد لتعويض الحجم المفقود أو تحديد بعض ملامح الوجه زي الشفايف والخدود وخط الفك والذقن، وكمان لتنعيم بعض الخطوط العميقة. الدكتور بيحدد نوع الفيلر والكمية والمكان المناسب حسب ملامح العميل واحتياجه.","details":[["دواعي الاستخدام","زيادة أو استعادة حجم الخدود، تحديد أو تكبير الشفايف بشكل متناسق، تحسين منطقة تحت العين حسب تقييم الدكتور، تحديد خط الفك والذقن، تحسين شكل الأنف في الحالات المناسبة، تنعيم خطوط الابتسامة (Nasolabial Lines) وخطوط الماريونيت (Marionette Lines)، وتعويض فقدان الحجم في بعض مناطق الوجه"],["الأماكن المتاحة","Lips, Cheeks, Under Eye, Jawline, Chin, Nose, Nasolabial Lines, Marionette Lines — والمكان المناسب ونوع الفيلر بيحدده الدكتور بعد الكشف"],["مدة الجلسة","حوالي 20-45 دقيقة، وممكن يتم استخدام كريم مخدر قبل الحقن، وبعض أنواع الفيلر نفسها فيها مادة مخدرة لتقليل الإحساس"],["النتيجة","الشكل بيظهر مباشرة بعد الحقن، وممكن يحصل تورم أو كدمات في البداية فالشكل النهائي محتاج وقت للاستقرار، وبيستقر غالبًا خلال حوالي أسبوعين حسب المنطقة واستجابة الجسم"],["مدة استمرار النتيجة","Lips: حوالي 6-12 شهر. Cheeks / Jawline: حوالي 12-18 شهر. Under Eye: حوالي 9-12 شهر أو أكتر. المدة تقديرية وليست ضمانًا، والدكتور يحدد التوقعات حسب الحالة والمنتج"],["ميزة مهمة","فيلر الـ Hyaluronic Acid يمكن إذابته باستخدام Hyaluronidase / Hyalase في الحالات اللي يرى فيها الطبيب إن الإذابة مناسبة، وده مش معناه إن كل مشكلة بعد الفيلر لازم تتذاب — القرار للطبيب حسب الحالة"],["مش مناسب لـ / لازم تتراجع مع الدكتور","الحمل أو الرضاعة، وجود التهاب أو عدوى نشطة في مكان الحقن، حساسية معروفة من مكونات الفيلر أو مواد التخدير، اضطرابات تخثر الدم غير المنضبطة، بعض أمراض المناعة أو الحالات الطبية الخاصة حسب تقييم الدكتور، ووجود فيلر سابق في نفس المنطقة خصوصًا لو المنتج أو تاريخه غير معروف"]],"products":[["Juvederm (جوفيديرم)","أمريكا (Allergan)","Ultra 2/3/4, Volbella للشفايف والخطوط الرفيعة، Volift للخطوط والـ Volume، Voluma للخدود والدقن، Volux للفك والدقن"],["Teoxane (تيوكسان)","سويسرا","RHA 1 خطوط رفيعة، RHA 2/3 خطوط وشفايف، RHA 4 Volume، Kiss للشفايف، Ultra Deep Volume عميق، Redensity I/II جودة البشرة وبعض استخدامات تحت العين"],["Neauvia (نيوفيا)","سويسرا","Intense Lips للشفايف، Intense/Intense Flux/Intense LV خطوط وحجم، Stimulate Volume + تحفيز الكولاجين، Man أنواع مخصصة للاستخدامات الرجالية"],["Croma (كروما)","النمسا","Volume وVolume Plus"],["Celosome (سيلوسوم)","كوريا الجنوبية","Soft خطوط رفيعة، Mid خطوط متوسطة، Strong خطوط عميقة، Implant تحديد وحجم"],["أنواع كورية أخرى معتمدة","كوريا الجنوبية","حسب المنتجات المتاحة، والدكتور هو اللي بيحدد النوع المناسب للحالة"]],"booking":["السعر للسرنجة الواحدة، وممكن الدكتور يستخدم أكتر من نوع أو أكتر من سرنجة في نفس الجلسة حسب الحالة","الـ Cannula بتتضاف على الفاتورة بس لو الدكتور استخدمها","ممنوع حقن أي فيلر العميل جايبه من خارج العيادة، والسرنجة مخصصة لشخص واحد فقط","المتبقي من السرنجة ممكن يُستخدم في Touch-up لنفس المريض فقط خلال شهر بحد أقصى، حسب سياسة العيادة وتوجيه الدكتور","الإذابة (Hyalase) مجانية لو الفيلر اتحقن جوه Allure، وبمقابل لو اتحقن برا Allure — لازم إبلاغ الدكتور قبل تأكيد الحجز ويلزم اختبار حساسية حسب بروتوكول العيادة","⚠️ الـ Agent لا يحدد نوع الفيلر المناسب للعميل من نفسه؛ النوع والكمية قرار الدكتور بعد التقييم، ولا يقرر صلاحية العميل للفيلر"],"care":[["قبل","يفضل تجنب Aspirin / Omega-3 / Vitamin E قبل الجلسة بحوالي أسبوع إذا وافق الطبيب. أدوية السيولة الموصوفة ما تتوقفش من العميل نفسه، لازم يرجع لطبيبها"],["قبل","إبلاغ الدكتور بأي حساسية معروفة (من الفيلر أو مواد التخدير)، وأي تاريخ سابق لحقن فيلر، وتأجيل الحقن عند وجود التهاب أو عدوى نشطة زي الـ Herpes"],["قبل","الحمل والرضاعة يتم إبلاغ الدكتور بيهم قبل الحجز"],["بعد","تورم أو كدمات بسيطة ممكن تحصل من يومين لأسبوع، والشفايف ممكن يكون فيها تورم أكتر"],["بعد","تجنب الرياضة العنيفة 24-48 ساعة، وتجنب الساونا والحرارة العالية والشمس المباشرة حوالي 48 ساعة أو حسب تعليمات الدكتور"],["بعد","تجنب المكياج حوالي 12 ساعة، وعدم تدليك أو الضغط على مكان الحقن إلا بتوجيه الطبيب، ويفضل النوم على الظهر أول ليلة"]],"say":[["الفيلر بيوجع؟","غالبًا الإحساس بسيط، وبنستخدم كريم مخدر، وبعض أنواع الفيلر نفسها فيها مخدر. ممكن تحسي بشكة أو ضغط بسيط أثناء الحقن"],["هيبان مصطنع؟","الهدف شكل متناسق وطبيعي مع ملامح الوجه، والدكتور بيحدد الشكل والكمية المناسبة بعد الكشف"],["لو ماعجبنيش؟","لو الفيلر Hyaluronic Acid، ممكن يكون قابل للإذابة بمادة خاصة (Hyaluronidase/Hyalase) لو الدكتور قرر إن الإذابة مناسبة"],["بتستخدموا فيلر إيه؟ وهل هو أصلي؟","عندنا أنواع وماركات مختلفة متاحة، والدكتور بيحدد الأنسب للحالة، والمنتجات من مصادر معتمدة حسب سياسة العيادة"],["أنا جايبة الفيلر معايا","للأسف مش بنقدر نحقن منتجات من خارج العيادة، علشان لازم نضمن مصدر المنتج وطريقة حفظه وسلامته"],["فاضل في السرنجة، أحتفظ بيه؟","المتبقي مش بيتحفظ لشخص تاني، ولو مناسب طبيًا ممكن يتعمل بيه Touch-up لنفس المريض بس خلال شهر بحد أقصى حسب سياسة العيادة وتوجيه الدكتور"]],"escalate":"ألم شديد أو بيزيد بشكل واضح، الجلد بيبيض أو بيزرق أو فيه تغير لون/تبقع غير طبيعي، برودة أو تغير واضح في الجلد بالمنطقة، أو أي تغيير في النظر — دي ممكن تكون علامات انسداد وعائي (Vascular Occlusion) ومحتاجة تقييم طبي عاجل","review":["اذكر 3 علامات طوارئ بعد الفيلر ممكن تدل على انسداد وعائي","إمتى إذابة الفيلر بتبقى مجانية وإمتى بتبقى بمقابل؟","فاضل نص سرنجة، ينفع تتعمل بيها Touch-up لعميل تاني؟","مين اللي بيحدد نوع وكمية الفيلر — الـ Agent ولا الدكتور؟"]}'::jsonb, 4);
insert into public.kb_articles (slug, kind, title, body, sort) values ('service:filler_body', 'service', 'فيلر الجسم (Body Filler)', '{"id":"filler_body","name":"فيلر الجسم (Body Filler)","branch":null,"summary":"فيلر مخصص لاستخدامات الجسم، بيتحقن بكميات أكبر من فيلر الوجه بهدف ملء أو تعديل شكل بعض المناطق من غير تدخل جراحي. مش سيليكون ومش مادة دائمة، وبيتم امتصاصه تدريجيًا مع الوقت.","details":[["دواعي الاستخدام","تحسين تجاويف جانب الورك (Hip Dips)، تجميل وتعديل شكل المؤخرة، تحسين مظهر ظهر اليد، تصحيح بعض التجاويف أو عدم التناسق بعد عمليات الشفط، وتحسين بعض المناطق اللي محتاجة تعويض حجم حسب تقييم الدكتور"],["المناطق المتاحة","Hip Dips, Buttocks, Back of Hands, وبعض التجاويف بعد Liposuction — والمنطقة المناسبة وكمية الفيلر بيحددها الدكتور بعد الكشف"],["مدة الجلسة","حوالي 45 دقيقة لساعة ونصف، مع تخدير موضعي حسب الإجراء وتقييم الدكتور"],["النتيجة","التغيير في الشكل بيظهر مباشرة بعد الحقن، والتورم ممكن يأثر على الشكل في البداية، والنتيجة بتستقر تدريجيًا خلال حوالي أسبوعين لشهر"],["مدة استمرار النتيجة","غالبًا حوالي 12-24 شهر، وبتختلف حسب المنطقة وكمية الفيلر والمنتج واستجابة الجسم (تقديرية وليست ضمانًا)"],["مش مناسب لـ / لازم تتراجع مع الدكتور","الحمل أو الرضاعة، وجود التهاب أو عدوى في المنطقة، وجود حقن سابق في نفس المكان بمادة غير معروفة، وجود أي إجراء أو مادة سابقة في المنطقة محتاجة تقييم، وأي حالة طبية أو جلدية غير واضحة"]],"products":[["Skin Fill (سكين فيل)","—","Body Filler، متاح بكميات 10 ml أو 50 ml، والدكتور بيحدد الكمية حسب المنطقة والحالة"],["Variofill (فاريوفيل)","—","Body Filler، عبوة 10 ml"],["Hyacorb (هياكورب)","—","Body Filler بدرجتين MLF1 / MLF2، والدكتور بيحدد النوع المناسب حسب المنطقة"]],"booking":["كمية الـ Filler المطلوبة بتتحدد في الكشف حسب المنطقة والشكل المطلوب، ومفيش تحديد عدد ml للعميل كرقم نهائي قبل الكشف","الـ Cannula بتتضاف على الفاتورة فقط لو الدكتور استخدمها","ممنوع حقن أي منتج العميل جايبه من خارج العيادة","⚠️ الـ Agent ما يحددش للعميل نوع المنتج أو عدد الـ ml المناسب من نفسه؛ ده بيتحدد بعد الكشف"],"care":[["قبل","اسأل العميل إذا كان عمل حقن سابق في نفس المنطقة، وسجل اسم المادة وتاريخ الحقن لو معروفين. لو المادة السابقة غير معروفة، لازم تبلغ الدكتور قبل تأكيد الإجراء"],["قبل","إبلاغ الدكتور بأي التهاب أو مشكلة جلدية في المنطقة، والحمل والرضاعة لازم يتم إبلاغ الدكتور بهم قبل الحجز"],["بعد","ممكن يحصل تورم أو زرقان أو إحساس بالشد، وغالبًا يستمر حوالي أسبوع"],["بعد","تجنب الرياضة العنيفة حوالي أسبوعين أو حسب تعليمات الدكتور، وممنوع التدليك أو المساج على المنطقة إلا بإذن الدكتور"],["بعد","تجنب الساونا والحرارة العالية إلا بعد السماح من الدكتور، والالتزام بتعليمات الدكتور بخصوص القعدة والنوم خلال الأيام الأولى"]],"say":[["ده زي السيليكون؟","لأ، ده Body Filler، مش سيليكون ولا مادة دائمة، وبيتم امتصاصه تدريجيًا مع الوقت"],["هحتاج كام ml؟","الكمية بتتحدد في الكشف حسب المنطقة وحجم التصحيح المطلوب والشكل اللي عايزاه، والدكتور هو اللي بيحدد الكمية المناسبة"],["أنا عاملة حقن قبل كده في نفس المكان","مهم جدًا نعرف اسم المادة وتاريخ الحقن لو متاح، ونسجلهم للدكتور علشان يقيّم المنطقة قبل أي إجراء جديد"],["النتيجة بتظهر إمتى؟","التغيير بيظهر من البداية، لكن التورم ممكن يأثر على الشكل، والنتيجة بتستقر تدريجيًا خلال حوالي أسبوعين لشهر"],["الفيلر بيدوم للأبد؟","لأ، فيلر الجسم مش مادة دائمة، ومدة استمراره بتختلف حسب المنطقة والمنتج والكمية واستجابة الجسم"]],"escalate":"ألم شديد أو بيزيد، سخونية واضحة، احمرار بينتشر، تغير غير طبيعي في لون الجلد، إفرازات من مكان الحقن، أو تورم شديد أو متزايد بشكل غير طبيعي — ما يتطمنش العميل إن ده طبيعي، وتتحول الحالة للدكتور فورًا","review":["اذكر منطقتين من المناطق المتاحة لفيلر الجسم","عميلة عاملة حقن قبل كده في نفس المكان بمادة مش عارفة اسمها، تعمل إيه؟","فيلر الجسم بيدوم قد إيه في المتوسط؟"]}'::jsonb, 5);
insert into public.kb_articles (slug, kind, title, body, sort) values ('service:filler_calcium', 'service', 'فيلر الكالسيوم (Calcium Fillers)', '{"id":"filler_calcium","name":"فيلر الكالسيوم (Calcium Fillers)","branch":null,"summary":"فيلر مادته كالسيوم هيدروكسيل أباتيت (CaHA)، بيدي حجم وتحديد على طول، وكمان بيحفز الكولاجين مع الوقت. أتقل من الفيلر العادي، ومابيدوبش بالـ Hyalase.","details":[["الاستخدامات","تحديد الفك والدقن، إبراز الخدود، خطوط الابتسامة العميقة، ظهر الإيد. وبتركيز مخفف لشد الجلد في الرقبة والصدر والجسم"],["مدة الجلسة","30-45 دقيقة"],["النتيجة","الحجم على طول، والشد وجودة الجلد بالتدريج خلال شهرين لـ 3 شهور"],["بتقعد قد إيه","12-18 شهر، وممكن أكتر حسب المنطقة"],["مش مناسب لـ","الشفايف وتحت العين (مش بيتحقن هناك)، الحمل والرضاعة، التهاب في المنطقة، والميل للكيلويد"]],"products":[["Radiesse (راديسس)","ألمانيا (Merz Aesthetics)","أشهر فيلر كالسيوم في العالم، للتحديد وتحفيز الكولاجين"],["Volassom (فولاسوم)","كوريا الجنوبية","فيلر كالسيوم كوري للحجم وتحفيز الكولاجين"],["فيلر كالسيوم كوري تاني","كوريا الجنوبية","أي نوع كوري معتمد عندنا، والدكتور بيحدد"]],"booking":["مابيدوبش بالـ Hyalase، أي سؤال عن إذابته يتحول للدكتور","مش بيتحقن في الشفايف أو تحت العين","نفس قواعد الفيلر: السرنجة لشخص واحد، والكانيولا بتتضاف لو اتستخدمت، وممنوع منتج من برا"],"care":[["بعد","ورم أو زرقان خفيف من يومين لأسبوع، والشغل عادي تاني يوم"],["بعد","مفيش رياضة عنيفة أو ساونا 48 ساعة، والتدليك حسب تعليمات الدكتور"]],"say":[["إيه الفرق بينه وبين الفيلر العادي؟","الفيلر العادي بيملى ويرطب. فيلر الكالسيوم أتقل وبيدي تحديد أقوى وبيحفز الكولاجين"],["ينفع للشفايف؟","لأ، مش بيتحقن في الشفايف أو تحت العين، للشفايف بنستخدم فيلر الهيالورونيك"],["لو ماعجبنيش يتشال؟","ده سؤال مهم للدكتور في الكشف، هو هيشرحلك كل حاجة قبل ما تاخدي القرار"]],"escalate":"نفس علامات طوارئ الفيلر (ألم شديد بيزيد، جلد بيبيض أو بيزرق أو مبقع، تغيير في النظر)، ولو في كتل تحت الجلد بعد أسابيع احجز له متابعة","review":["إيه المنطقتين اللي فيلر الكالسيوم مش بيتحقن فيهم؟","عميلة سألت: فيلر الكالسيوم بيدوب لو ماعجبنيش؟ ترد تقول إيه؟"]}'::jsonb, 6);
insert into public.kb_articles (slug, kind, title, body, sort) values ('service:botox', 'service', 'البوتوكس (Botox)', '{"id":"botox","name":"البوتوكس (Botox)","branch":null,"summary":"البوتوكس هو Botulinum Toxin بيقلل انقباض عضلات معينة بشكل مؤقت، وده بيساعد على تقليل التجاعيد اللي بتظهر مع حركة العضلات، مع الحفاظ على شكل وتعبيرات الوجه بشكل طبيعي حسب الجرعة والمكان. وممكن استخدامه كمان في بعض حالات فرط التعرق وابتسامة اللثة وحالات أخرى حسب تقييم الدكتور.","details":[["دواعي الاستخدام - الوجه","خطوط الجبهة، خطوط بين الحاجبين، خطوط وكرمشة جانب العين، رفع الحاجب، تصغير عضلة الفك (Masseter)، ابتسامة اللثة (Gummy Smile)، وMeso Botox حسب تقييم الدكتور"],["دواعي الاستخدام - فرط التعرق","تحت الإبط، اليدين، القدمين — واختيار المنطقة والجرعة وعدد الوحدات بيحدده الدكتور"],["مدة الجلسة","حوالي 10-20 دقيقة بإبر رفيعة جدًا"],["النتيجة","تبدأ تظهر عادةً خلال 3-5 أيام، والنتيجة الكاملة بتبان تقريبًا خلال أسبوعين، والمدة غالبًا 3-6 شهور وبتختلف حسب المنطقة واستجابة الجسم. تأثير علاج فرط التعرق ممكن يستمر لفترة أطول في بعض الحالات"],["المتابعة والـ Retouch","بوتوكس الوجه: يمكن عمل Retouch بعد أسبوعين لو احتاج الدكتور، والـ Retouch المجاني حسب سياسة الحجز لبوتوكس الوجه فقط حتى 50 وحدة. مفيش Retouch مجاني للإبط أو اليدين أو القدمين أو Gummy Smile أو Meso Botox أو البوتوكس بالوحدة — لازم توضيح سياسة الـ Retouch للعميل قبل تأكيد الحجز"],["مش مناسب لـ / بلّغ الدكتور","الحمل والرضاعة، بعض الأمراض العصبية والعضلية (زي Myasthenia Gravis)، وجود التهاب أو عدوى في مكان الحقن، حساسية معروفة تجاه Botulinum Toxin أو أحد مكونات المنتج، وأي أدوية أو حالات طبية مهمة يتم إبلاغ الدكتور بيها قبل الإجراء"]],"products":[["Botox (Allergan)","أمريكا","المنتج الأصلي من Allergan، من منتجات Botulinum Toxin المتاحة"],["Dysport (Ipsen)","فرنسا","من نفس فئة Botulinum Toxin"],["Metox / Korean Botulinum Toxin","كوريا الجنوبية","منتجات Botulinum Toxin كورية معتمدة حسب المتاح"]],"booking":["الوحدة بـ 90 جنيه، وعدد الوحدات النهائي بيحدده الدكتور حسب المنطقة والحالة","Botox الوجه حتى 50 وحدة له سعر حسب سياسة الحجز، مع Retouch مجاني بعد أسبوعين حسب الشروط المذكورة، ومفيش Retouch مجاني للمناطق أو الخدمات المستثناة","Allergan وDysport ضمن فئة سعرية واحدة حسب سياسة الأسعار، والمنتجات الكورية لها فئة سعرية مختلفة","⚠️ عدد الوحدات النهائي ما بيتأكدش للعميل قبل تقييم الدكتور"],"care":[["قبل","إبلاغ الدكتور بأي أمراض عصبية أو عضلية، أو حمل أو رضاعة، أو حساسية معروفة، أو أدوية/مكملات قد تؤثر على النزيف أو ظهور الكدمات"],["قبل","ممنوع إيقاف أي دواء موصوف، خصوصًا مميعات الدم، من تلقاء نفس العميل؛ الطبيب المعالج هو اللي يحدد. يفضل الحضور بوجه نظيف وخالٍ من المكياج في حالة بوتوكس الوجه"],["بعد","عدم الاستلقاء أو النوم 4 ساعات بعد الحقن، وعدم فرك أو تدليك أماكن الحقن 24 ساعة"],["بعد","تجنب الرياضة الشديدة والساونا والحرارة العالية لمدة 24 ساعة، وممكن يظهر احمرار بسيط أو صداع خفيف أو كدمات بسيطة عند بعض الحالات"],["بعد بوتوكس الوجه","لو العميل محتاج Retouch، يتم تحديد متابعة بعد أسبوعين حسب سياسة الحجز وتقييم الدكتور"]],"say":[["وشي هيبقى متخشب؟","الهدف إن الجرعة تتحدد حسب المنطقة والحالة بحيث تقل حركة العضلات المسؤولة عن الخطوط مع الحفاظ على تعبيرات الوجه بشكل مناسب"],["لو بطلته التجاعيد هتزيد؟","لا، مع انتهاء تأثير البوتوكس العضلات بتستعيد نشاطها تدريجيًا، والتجاعيد بترجع لطبيعتها حسب حالة البشرة والعمر وحركة العضلات"],["ينفع للعرق؟","أيوه، البوتوكس ممكن يُستخدم لتقليل فرط التعرق في مناطق زي الإبط واليدين والقدمين، والجرعة وطريقة العلاج بيحددها الدكتور"],["إيه الفرق بين الأمريكي والكوري؟","المنتجات المختلفة كلها من فئة Botulinum Toxin، لكن بتختلف الشركة والمنتج وبلد المنشأ، والدكتور بيحدد الأنسب حسب الحالة والمتاح"],["فيه Retouch ببلاش؟","في بوتوكس الوجه حسب سياسة الحجز، ويكون بعد أسبوعين. أما الإبط واليدين والقدمين وGummy Smile وMeso Botox والبوتوكس بالوحدة، فلا يوجد Retouch مجاني"]],"escalate":"صعوبة في البلع أو الكلام أو التنفس، زغللة أو اضطراب واضح في النظر، أو ضعف عضلي منتشر أو غير معتاد — تستدعي تقييم طبي عاجل. أما تهدل الجفن أو الحاجب بعد الحقن فيتم حجز Follow-up مع الدكتور للتقييم","review":["عميل عمل بوتوكس للعرق وطالب Retouch مجاني، ترد تقول إيه؟","نتيجة البوتوكس بتبان إمتى؟ وبتكمل إمتى؟","إيه أهم تعليمة لأول 4 ساعات بعد الحقن؟","إيه الفرق بين تهدل الجفن وصعوبة التنفس من ناحية التصرف المطلوب؟"]}'::jsonb, 7);
insert into public.kb_articles (slug, kind, title, body, sort) values ('service:skinbooster', 'service', 'سكين بوستر (Skin Boosters)', '{"id":"skinbooster","name":"سكين بوستر (Skin Boosters)","branch":null,"summary":"حقن سطحية دقيقة، غالبًا بـ Hyaluronic Acid بتركيبة مخصصة لتحسين ترطيب وجودة البشرة: ترطيب عميق، نعومة وإشراقة، ومرونة أكتر. عكس فيلر الوجه، الهدف الأساسي تحسين جودة البشرة وترطيبها مش تغيير حجم أو ملامح الوجه.","details":[["دواعي الاستخدام","البشرة الجافة أو الباهتة، قلة الترطيب، تحسين النضارة والإشراقة، تحسين نعومة وملمس البشرة، الخطوط الرفيعة، دعم مرونة البشرة، وكإجراء وقائي أو تكميلي مع خدمات أخرى، أو قبل المناسبات مع مراعاة وقت التعافي المتوقع"],["الأماكن","الوجه، تحت العين حسب نوع المنتج وتقييم الدكتور، الرقبة، منطقة الصدر، وظهر اليد — مش كل منتج مناسب لكل منطقة، والدكتور بيحدد المنتج وطريقة الحقن"],["البروتوكول","لأحسن نتيجة: جلسة كل شهر × 3 جلسات، وبعدها ممكن جلسة صيانة كل 6 شهور حسب حالة البشرة وتقييم الدكتور. البروتوكول النهائي ممكن يختلف حسب المنتج وحالة العميل"],["مدة الجلسة","حوالي 20-30 دقيقة، مع إمكانية استخدام كريم مخدر حسب الحالة والمنطقة"],["النتيجة","النضارة والترطيب ممكن يبدأوا يظهروا خلال أسبوع لأسبوعين، وتتحسن مع استكمال الكورس، ومدة الاستمرارية بتختلف حسب المنتج والبشرة ونمط الحياة"],["مش مناسب لـ / بلّغ الدكتور","الحمل والرضاعة، وجود التهاب أو عدوى نشطة في منطقة العلاج، وجود حبوب ملتهبة أو جروح في المنطقة، حساسية معروفة تجاه المادة أو أحد مكوناتها، وأي حالة طبية أو دوائية مهمة يجب إبلاغ الدكتور بها قبل الحقن"]],"products":[["RRS","إسبانيا","RRS HyaLift للنضارة وتحسين جودة البشرة، RRS Long Lasting (اللولا/LOLA) لترطيب وتحسين جودة البشرة، RRS Eyes مخصص لتحت العين"],["Xela Rederm","سويسرا","3 تركيزات 1.1%/1.8%/2.2%، هيالورونيك أسيد مع مكونات مخصصة للترطيب والمرونة وتجديد البشرة"],["Profhilo","إيطاليا (IBSA)","بيتحقن في نقاط محددة بدل التوزيع على كامل المنطقة، بيرطب ويحسن جودة وشد البشرة، وفيه Profhilo Structura لبروتوكولات تحسين الامتلاء وجودة الأنسجة"],["Signature","إيطاليا","تركيز مرتفع من Hyaluronic Acid مع ببتيدات وأحماض أمينية حسب المنتج"],["Neauvia Hydro Deluxe","سويسرا","مخصص للترطيب وتحسين جودة البشرة، تركيبة تتضمن CaHA حسب المنتج"]],"booking":["السعر حسب السرنجة أو الفيال وفق المنتج، والنوع والكمية بيحددهم الدكتور","ممنوع استخدام منتج يحضره العميل من الخارج","في حالة وجود كمية متبقية، يتم التعامل معها حسب سياسة الـ Touch-up المعتمدة ولنفس المريض فقط","لو العميل موافق على الكورس، يفضل حجز الجلسات الثلاثة من البداية حسب المواعيد المتاحة: جلسة كل شهر × 3"],"care":[["قبل","الحضور ببشرة نظيفة وخالية من المكياج والزيوت، وإبلاغ الدكتور بأي حساسية معروفة أو مواد اتحقنت سابقًا في نفس المنطقة"],["قبل","تأجيل الجلسة عند وجود التهاب أو عدوى نشطة، وإبلاغ الدكتور بأي أدوية أو مكملات قد تزيد فرصة الكدمات (من غير إيقاف أي دواء موصوف من تلقاء العميل)"],["بعد","ممكن يظهر نقاط صغيرة أو بروز بسيط مكان الحقن، احمرار خفيف، زرقان بسيط، أو تورم خفيف — وغالبًا بتتحسن خلال يوم أو يومين"],["بعد","عدم وضع المكياج 24 ساعة، عدم تدليك الوجه، تجنب الساونا والحرارة العالية، وتجنب الرياضة العنيفة 48 ساعة، مع استخدام واقي الشمس حسب تعليمات الدكتور"],["للكورس","لو العميل حجز 3 جلسات، يتم تذكيره بموعد الجلسة التالية بعد شهر"]],"say":[["هو زي الفيلر؟","من نفس عائلة المواد المستخدمة في بعض منتجات الحقن، لكن الهدف مختلف. السكين بوستر بيركز على ترطيب وجودة البشرة، بينما فيلر الوجه بيُستخدم لإضافة حجم أو تحديد مناطق معينة"],["عندي فرح كمان أسبوعين، ينفع؟","ممكن، لكن الأفضل يكون فيه وقت كافي قبل المناسبة لأي احمرار أو تورم أو زرقان محتمل، ويفضل مناقشة التوقيت مع الدكتور"],["هيقعد قد إيه؟","غالبًا كورس من 3 جلسات، جلسة كل شهر، وبعدها جلسات صيانة حسب تقييم الدكتور"],["عندكم حاجة لتحت العين؟","أيوه، فيه منتجات مخصصة زي RRS Eyes، لكن الدكتور لازم يقيّم المنطقة ويحدد الأنسب"],["هل هيغير شكل وشي؟","الهدف الأساسي تحسين ترطيب وجودة البشرة، مش تغيير ملامح الوجه زي الفيلر"]],"escalate":"تورم شديد أو بيزيد، احمرار شديد أو منتشر، سخونية واضحة في المنطقة، ألم شديد أو متزايد، كتل مؤلمة أو تورم غير معتاد بعد أيام، أو أي تغير واضح أو غير طبيعي في لون الجلد","review":["إيه بروتوكول السكين بوستر لأحسن نتيجة؟","إيه الاسم المشهور لـ RRS Long Lasting؟","إيه الفرق بين السكين بوستر وفيلر الوجه في الهدف؟","عميلة عندها فرح كمان أسبوعين وعايزة تعمل سكين بوستر، ترد تقول إيه؟"]}'::jsonb, 8);
insert into public.kb_articles (slug, kind, title, body, sort) values ('service:plla', 'service', 'محفزات الكولاجين PLLA & Collagen Biostimulators', '{"id":"plla","name":"محفزات الكولاجين PLLA & Collagen Biostimulators","branch":null,"summary":"مواد بيتم امتصاصها تدريجيًا، وبعض أنواعها بتحفز الجسم على إنتاج كولاجين جديد، فتحسن الامتلاء وجودة الجلد والشد بيظهر بشكل تدريجي بدل ما يكون زي الفيلر التقليدي اللي بيدي حجم مباشر. طريقة التأثير والنتيجة والـ aftercare بتختلف حسب نوع المنتج، والدكتور هو اللي بيحدد المادة والكمية المناسبة.","details":[["الاستخدامات","فقدان امتلاء الوجه مع السن أو بعد فقدان الوزن، بعض حالات الترهل الخفيف، تحسين جودة الجلد وتحفيز الكولاجين، وبعض مناطق الجسم حسب نوع المنتج والبروتوكول زي المؤخرة والفخذين والركب"],["عدد الجلسات","غالبًا 2-3 جلسات بفاصل حوالي 4-6 أسابيع، لكن البروتوكول النهائي بيحدده الدكتور حسب المنتج والحالة"],["مدة الجلسة","حوالي 30-45 دقيقة"],["النتيجة","ممكن يظهر امتلاء أولي بعد الجلسة لكنه قد يكون مؤقت بسبب السائل المستخدم أثناء الحقن، والتحسن الناتج عن تحفيز الكولاجين بيظهر تدريجيًا خلال الأسابيع التالية، وبعض المنتجات قد يستمر تأثيرها لسنتين أو أكتر حسب المادة والحالة والبروتوكول"],["مش مناسب لـ / بلّغ الدكتور","الحمل والرضاعة، وجود التهاب أو عدوى نشطة في منطقة الحقن، الميل لتكوين Keloid حسب تقييم الطبيب، الشفايف أو منطقة حول العين لو المنتج غير مخصص لهذه المناطق، ووجود مادة حقن سابقة غير معروفة في نفس المنطقة"]],"products":[["Advance Lactic","إيطاليا","PLLA، ويتوفر حسب الكمية: 1، 2.5، 5 مل أو فيال كامل"],["Rich PL","إيطاليا (Promoitalia)","يجمع Hyaluronic Acid وPLLA"],["Olidia","كوريا الجنوبية","PLLA لتحفيز الكولاجين للوجه والجسم حسب البروتوكول"],["Pleujuv","كوريا الجنوبية","يجمع Hyaluronic Acid وPLLA"],["PiNkLLA","كوريا الجنوبية","PLLA مع PN ومكونات أخرى حسب المنتج"]],"booking":["المنتج والكمية بيحددهم الدكتور، والـ Advance Lactic بيتباع حسب الكمية/المل، والمنتجات الأخرى حسب نظام بيع المنتج والفيال","⚠️ الـ PLLA لا يتم إذابته بحقنة زي الـ Hyaluronic Acid Filler","لو العميل قلقان من النتيجة أو بيسأل عن إمكانية إزالة المادة، يتم تحويل السؤال للدكتور","لازم شرح تعليمات الـ aftercare للمريض قبل مغادرة العيادة"],"care":[["قبل","إبلاغ الدكتور بأي حقن أو مواد سابقة في نفس المنطقة، وأي حساسية أو التهاب أو مشكلة جلدية في المنطقة، والحمل أو الرضاعة، وأي أدوية أو علاجات حالية"],["بعد","ممكن يحصل تورم أو كدمات خفيفة لعدة أيام، وممكن يكون فيه امتلاء واضح أول يوم يقل بعد زوال السائل المستخدم أثناء الحقن"],["بعد","الالتزام بتعليمات الدكتور الخاصة بالتدليك، ولو طلب قاعدة 5-5-5: 5 دقايق، 5 مرات يوميًا، لمدة 5 أيام"],["بعد","تجنب الساونا والتعرض المباشر للشمس حسب تعليمات الدكتور، وعدم الضغط أو تدليك المنطقة بطريقة مختلفة عن التعليمات"]],"say":[["إيه الفرق بينه وبين الفيلر؟","الفيلر التقليدي بيستخدم مادة لإضافة حجم بشكل مباشر، أما محفزات الكولاجين فبعض أنواعها بتحفز الجسم على تكوين كولاجين، فالتحسن بيظهر تدريجيًا حسب المادة والحالة"],["ليه النتيجة راحت بعد كام يوم؟","ممكن يكون جزء من الامتلاء اللي ظهر أول يوم ناتج عن السائل المستخدم أثناء الحقن، وده ممكن يقل بعد فترة قصيرة، أما نتيجة تحفيز الكولاجين فبتظهر تدريجيًا خلال الأسابيع التالية"],["ليه لازم أدلك؟","لو الدكتور طلب التدليك، فده جزء من الـ aftercare الخاص بالمادة المستخدمة، وبيتم بالطريقة والمدة اللي الدكتور بيحددها"],["لو مش عاجباني النتيجة، ممكن نفكها؟","الـ PLLA مش بيتفك بحقنة زي بعض أنواع الـ Hyaluronic Acid Filler، فالأفضل تناقشي الدكتور قبل الجلسة عن النتيجة المتوقعة وأي مخاوف عندك"]],"escalate":"كتل أو Nodules مستمرة أو بتظهر بعد فترة من الجلسة، احمرار أو سخونية بتزيد، ألم شديد أو متزايد، تورم غير معتاد أو مستمر، إفرازات أو علامات التهاب، أو أي تغير واضح وغير معتاد في لون الجلد","review":["إيه هي قاعدة 5-5-5؟","هل الـ PLLA بتتفك زي الفيلر؟","اذكر منتجين PLLA إيطاليين عندنا","عميل قلقان من النتيجة وسأل ممكن نفكها؟ ترد تقول إيه؟"]}'::jsonb, 9);
insert into public.kb_articles (slug, kind, title, body, sort) values ('service:exosomes', 'service', 'الإكزوزومز والـ PDRN (Exosomes & PDRN)', '{"id":"exosomes","name":"الإكزوزومز والـ PDRN (Exosomes & PDRN)","branch":null,"summary":"الإكزوزومز والـ PDRN من المواد المستخدمة ضمن بروتوكولات تجديد وتحسين جودة البشرة. الإكزوزومز بتدعم تجدد وتحسين جودة الجلد وفروة الرأس، والـ PDRN بتُستخدم ضمن بروتوكولات تجديد البشرة وتحسين مظهرها وملمسها. نوع المنتج وطريقة الاستخدام والكمية بيحددهم الدكتور.","details":[["دواعي الاستخدام","نضارة البشرة، ملمس البشرة، الخطوط الرفيعة، المسام، آثار الحبوب، البشرة المجهدة أو الباهتة، منطقة تحت العين حسب تقييم الدكتور، وبعض حالات تساقط وضعف الشعر حسب المنتج والبروتوكول"],["طريقة التطبيق","حسب المنتج والبروتوكول: بالحقن، أو مع Derma Pen 4، أو الديرمابن العادي، أو VIVACE، أو Fractional Laser CO2، أو أجهزة/إجراءات أخرى حسب البروتوكول"],["عدد الجلسات","غالبًا 3-5 جلسات بفواصل تقريبية 2-4 أسابيع، والعدد النهائي يحدده الدكتور حسب الحالة والمنتج وطريقة التطبيق"],["النتيجة","ممكن يظهر تحسن في النضارة خلال فترة قصيرة، وتحسن ملمس وجودة البشرة بيظهر تدريجيًا. في بروتوكولات الشعر، تقييم النتيجة يحتاج وقت أطول وقد يبدأ التحسن خلال عدة أشهر"]],"products":[["Exosignal","Promoitalia - إيطاليا","Exosomes لتجديد وتحسين جودة البشرة"],["Exosignal Hair","Promoitalia - إيطاليا","بروتوكول مخصص لفروة الرأس والشعر"],["V-Tech Exosomes","Promoitalia - إيطاليا","Exosomes مع PDRN"],["Dives Platinum Ultra 4","Dives Med - ألمانيا","Exosomes مع PDRN"],["Revital PDRN","إسبانيا","PDRN لتجديد وتحسين مظهر البشرة"],["Amber Saffron","بولندا","Skin Booster بخلاصة الزعفران (وليس Exosomes/PDRN مباشرة)"],["Yaqoot","إيطاليا","Skin Booster للنضارة والترطيب (وليس Exosomes/PDRN مباشرة)"]],"booking":["الإكزوزومز والـ PDRN ممكن يتعملوا مع جلسة جهاز أخرى (Derma Pen 4، الديرمابن العادي، VIVACE، Fractional Laser CO2، أو غيرها حسب تقييم الدكتور)","لو اتعمل مع جلسة جهاز: إجمالي السعر = سعر جلسة الجهاز + سعر المنتج (سعر المادة لا يشمل سعر جلسة الجهاز)","مثال: Fractional Laser CO2 للوجه 1000 جنيه + Exosignal 1 ml بـ 1800 جنيه = الإجمالي 2800 جنيه","سعر المنتج حسب النوع والكمية، وسعر الجهاز بيتحسب منفصل، والدكتور هو اللي بيحدد المنتج والكمية وطريقة الاستخدام","لو البروتوكول مختلف أو فيه إجراء إضافي، يتم الرجوع لمكتب الأسعار/الدكتور قبل تأكيد السعر"],"care":[["قبل","اسأل عن وجود حساسية معروفة أو ردود فعل سابقة تجاه أي منتج، ولو العميل ذكر حساسية من السمك سجّل المعلومة وبلّغ الدكتور"],["قبل","لو فيه حمل أو رضاعة أو التهاب أو عدوى نشطة في منطقة العلاج، الرجوع للدكتور قبل الحجز. وفي حالة مرض مزمن أو أدوية مستمرة، إبلاغ الدكتور"],["بعد","ممكن يحصل احمرار بسيط ليوم أو يومين، نقط صغيرة في حالة الحقن، تورم بسيط، أو كدمات بسيطة في بعض الحالات"],["بعد","تجنب المكياج 24 ساعة، وتجنب Retinol والأحماض والمقشرات لعدة أيام، وتجنب الساونا والحرارة الشديدة 48 ساعة، واستخدام Sunscreen يوميًا، وعدم فرك أو تدليك المنطقة بعنف"]],"say":[["ينفع أعمل الـ Exosomes مع الديرمابن؟","أيوه، ممكن يتعمل مع Dermapen 4 أو الديرمابن العادي حسب البروتوكول، والدكتور بيحدد المنتج والكمية المناسبة"],["ينفع مع الـ VIVACE؟","أيوه، ممكن يتعمل مع VIVACE حسب تقييم الدكتور والبروتوكول"],["ليه السعر زاد لما اتعمل مع الفراكشنال؟","لأن فيه تكلفة جلسة الجهاز بالإضافة لتكلفة الـ Exosomes أو الـ PDRN المستخدم"],["لو هعمل Fractional + Exosignal، الحساب بيكون إزاي؟","سعر جلسة الفراكشنال بيتحسب منفصل، بالإضافة لسعر الـ Exosignal حسب الكمية. مثلًا فراكشنال للوجه 1000 جنيه + Exosignal 1 ml بـ 1800 جنيه = الإجمالي 2800 جنيه"],["هحتاج كام جلسة؟","عدد الجلسات بيختلف حسب الحالة والمنتج والبروتوكول، والدكتور هو اللي بيحدد الخطة المناسبة"]],"escalate":"تورم شديد أو متزايد، طفح منتشر، صعوبة في التنفس (حالة طارئة تحتاج تصرف طبي فوري خصوصًا لو مع تورم الوجه/الشفايف)، ألم شديد أو غير معتاد، سخونية واحمرار متزايد بشكل واضح، أو إفرازات أو علامات عدوى","review":["لو العميلة هتعمل فراكشنال مع إكزوزومز، السعر بيتحسب إزاي؟","الـ PDRN مستخلص من إيه؟ ومين بيسأل عن حساسية السمك؟","اذكر منتج فيه Exosomes مع PDRN مع بعض"]}'::jsonb, 10);
insert into public.kb_articles (slug, kind, title, body, sort) values ('service:meso', 'service', 'الميزوثيرابي (Mesotherapy)', '{"id":"meso","name":"الميزوثيرابي (Mesotherapy)","branch":null,"summary":"حقن سطحي بإبر رفيعة جدًا، بيتم فيه حقن مواد مختلفة حسب المشكلة زي الفيتامينات والأحماض الأمينية والمغذيات ومكونات مخصصة للبشرة أو الشعر. الدكتور هو اللي بيحدد نوع المادة والمنتج والكمية وعدد الجلسات حسب الحالة.","details":[["الاستخدامات - بشرة","تحسين النضارة والترطيب، مظهر البشرة المرهقة والباهتة، بعض حالات التصبغات أو تفاوت لون البشرة، الهالات حسب تقييم الدكتور، بعض حالات حب الشباب وآثاره، بعض حالات الاحمرار، وتحسين ملمس وجودة البشرة"],["الاستخدامات - شعر","المساعدة في تقوية الشعر وتقليل التساقط في بعض الحالات، دعم صحة فروة الرأس، وتحسين كثافة ومظهر الشعر حسب سبب التساقط"],["الاستخدامات - جسم","بعض حالات السيلوليت وبعض الدهون الموضعية حسب تقييم الدكتور. الميزو مش علاج واحد ثابت؛ المادة المستخدمة بتختلف حسب المنطقة والمشكلة"],["عدد الجلسات","غالبًا كورس 4-6 جلسات، بمعدل جلسة كل 2-3 أسابيع، وبعد الكورس ممكن يحتاج العميل جلسات صيانة حسب تقييم الدكتور. العدد النهائي ما بيتأكدش للعميل قبل تقييم الدكتور"],["مدة الجلسة","حوالي 20-30 دقيقة، وقد يتم استخدام كريم مخدر حسب المنطقة ونوع الإجراء"],["النتيجة","تدريجية غالبًا، وممكن تبدأ تبان بشكل أوضح بعد الجلسة الثانية أو الثالثة، وبتختلف حسب المشكلة والمنطقة والمادة المستخدمة واستجابة الجسم وعدد الجلسات"],["مش مناسب لـ / بلّغ الدكتور","الحمل والرضاعة، حساسية معروفة من أحد مكونات المادة، التهاب أو عدوى نشطة في منطقة الحقن، جروح مفتوحة في المنطقة، وأي تاريخ تحسسي أو مشكلة طبية مرتبطة بالمادة المستخدمة"]],"products":[["Promoitalia (برومو إيطاليا)","إيطاليا","White In للتفتيح، Hair Plus للشعر وتساقطه، Upgrade للترطيب العميق وتحسين مظهر البشرة، Hydro للترطيب، Light Eyes لتحت العين والهالات، NucleoSkin لتجديد البشرة، Celluform/Celluform Plus للسيلوليت"],["Cell Pro (سيل برو)","أيرلندا","Hair / Hair Boost / PureCell للشعر، وكمان Lipocell Pro وVitacell وRegen Pro وReCell Pro وLumicell Pro وMarkless، كل منتج له استخدام مختلف والدكتور بيحدد الأنسب"],["Cellbooster (سيل بوستر)","سويسرا (Suisselle)","Cellbooster Hair للشعر وفروة الرأس، Cellbooster Glow لنضارة وترطيب البشرة"],["Reva (ريفا)","—","Reva Acne لحب الشباب، Reva Red للاحمرار، Reva Scar لآثار وندبات البشرة"],["Nanostatic (نانوستاتيك)","مصر","Anadrox، Biosoft، Dermaglow، Hair، Melaglow، Melasnow، Renewmax، Aqua Tone"]],"booking":["السعر الأساسي هو سعر مادة الحقن حسب الكمية وفق سياسة الأسعار، والسعر يبدأ من 400 جنيه، والتكلفة النهائية تعتمد على المادة والكمية والدكتور والتقييم","السعر موحد حسب سياسة الفروع، بما فيها التجمع","لو الميزو اتعمل مع Dermapen أو VIVACE أو Fractional Laser، يتم إضافة سعر الإجراء الآخر حسب التسعير","الدكتور بيحدد نوع المادة والكمية والمنطقة وعدد الجلسات ومدة الكورس","⚠️ المنتجات المتاحة ممكن تختلف حسب المخزون، وما ينفعش نضمن للعميل منتج معين قبل التأكد من المتاح وقرار الدكتور"],"care":[["قبل","تنظيف المنطقة جيدًا من المكياج والزيوت قبل الجلسة، وإبلاغ الدكتور بأي حساسية معروفة أو مواد/جلسات سابقة في نفس المنطقة"],["قبل","تجنب المقشرات القوية قبل الجلسة بعدة أيام حسب تعليمات الطبيب، وتأجيل الجلسة عند وجود التهاب أو عدوى نشطة أو جروح مفتوحة"],["بعد","ممكن تظهر نقط حمراء صغيرة مكان الحقن، تورم خفيف، أو زرقان بسيط، وغالبًا الأعراض البسيطة بتتحسن خلال يوم أو يومين"],["بعد","تجنب المكياج 24 ساعة حسب تعليمات الطبيب، وتجنب الشمس المباشرة واستخدام واقي شمس، وتجنب الساونا والحرارة العالية 48 ساعة، وعدم حك أو فرك المنطقة"],["بعد ميزو الشعر","تجنب غسل الشعر لمدة 12-24 ساعة حسب تعليمات الطبيب"]],"say":[["الميزو بيعمل إيه للبشرة؟","بيساعد على تحسين النضارة والترطيب ومظهر البشرة المرهقة، حسب نوع المادة المستخدمة"],["هيوقف وقوع الشعر؟","الميزو ممكن يساعد في بعض حالات تساقط الشعر، لكن لازم الدكتور يحدد سبب التساقط الأول، وممكن يطلب تحاليل أو تقييمات إضافية حسب الحالة"],["في حاجة للسيلوليت؟","في منتجات مخصصة زي Celluform وCelluform Plus، لكن الدكتور هو اللي بيحدد إذا كانت مناسبة للحالة وعدد الجلسات"],["النتيجة بتبان من أول جلسة؟","ممكن يحصل تحسن، لكن النتيجة عادةً تدريجية وبتبان بشكل أوضح مع استكمال الكورس"],["أقدر أختار المنتج بنفسي؟","الأفضل إن اختيار المادة والمنتج يكون بناءً على تقييم الدكتور ونوع المشكلة"]],"escalate":"احمرار شديد أو بيزيد وينتشر، سخونية واضحة في المنطقة، صديد أو إفرازات، ألم شديد أو متزايد، تورم شديد أو غير معتاد، أو كتل مؤلمة بتظهر أو تستمر بعد أيام","review":["اذكر 3 منتجات ميزو للشعر موجودين عندنا","كورس الميزو غالبًا كام جلسة، والمسافة بينهم قد إيه؟","إيه المنتج المصري في الميزو؟","عميل سأل ممكن يختار المنتج بنفسه، ترد تقول إيه؟"]}'::jsonb, 11);
insert into public.kb_articles (slug, kind, title, body, sort) values ('service:prp', 'service', 'البلازما PRP', '{"id":"prp","name":"البلازما PRP","branch":null,"summary":"بلازما غنية بالصفائح الدموية بتتحضر من دم العميل نفسه. بنسحب عينة دم صغيرة، وبنجهزها بأنابيب وجهاز مخصص لفصل البلازما، وبعدها بتستخدم حسب المنطقة والبروتوكول اللي يحدده الدكتور للمساعدة في تجديد وتحسين حالة الشعر أو البشرة.","details":[["الاستخدامات للشعر","بعض حالات تساقط الشعر وضعفه، والمساعدة في تحسين كثافة ومظهر الشعر حسب سبب التساقط"],["الاستخدامات للبشرة","تحسين نضارة وجودة البشرة، بعض حالات الهالات حسب السبب، وممكن تُستخدم مع Fractional Laser أو Dermapen ضمن خطة علاجية لتحسين الملمس والمسام والآثار حسب تقييم الدكتور"],["عدد الجلسات","غالبًا 3-4 جلسات بفاصل حوالي شهر، وبعدها قد تكون جلسات صيانة كل 3-6 شهور حسب الحالة واستجابة العميل"],["مدة الجلسة","حوالي 45 دقيقة، شاملة سحب الدم والتحضير والإجراء"],["النتيجة","تدريجية وتختلف من حالة للتانية: البشرة قد يظهر التحسن خلال الأسابيع التالية، والشعر يحتاج وقت أطول وغالبًا يتم تقييم التحسن خلال 2-3 شهور أو أكتر"],["مش مناسب لـ / بلّغ الدكتور","بعض أمراض الدم أو اضطرابات الصفائح، بعض حالات الأورام، وجود عدوى أو التهاب نشط في منطقة العلاج، الحمل حسب تقييم الطبيب، وأي أدوية أو حالات طبية مؤثرة على النزيف أو التئام الجلد"]],"products":[["PT Tube","—","الأنبوبة الأساسية لتحضير البلازما"],["Golden Tube / Italian Tubes","—","أنابيب مخصصة لتحضير البلازما حسب النظام المستخدم"],["Zoom PRP / Zoom 15 ML","—","أنابيب Zoom بأحجام/أنظمة مختلفة حسب البروتوكول"],["Zoom Biotin","—","نوع مخصص ضمن بروتوكولات الشعر حسب اختيار الطبيب"],["Zoom HA","—","نوع مخصص ضمن بروتوكولات البشرة حسب اختيار الطبيب"],["Raimelan PRP / Raimelan Biotin","—","أنابيب مستخدمة ضمن بروتوكولات PRP حسب الاستخدام، والـ Biotin مخصوصة للشعر"],["Plasma Gel","—","نوع مختلف من تحضير البلازما على شكل Gel، ويحدد الطبيب استخدامها"]],"booking":["لكل نوع سعر جلسة وسعر Package 3 Sessions حسب مكتب الأسعار","الـ Package يتكون من 3 جلسات من نفس النوع، ولا يتم تقسيمه بين أنواع مختلفة","للشعر قد يُستخدم Zoom Biotin، وللبشرة قد يُستخدم Zoom HA، لكن الاختيار النهائي للدكتور","الصيانة بعد الكورس حسب الحالة، وغالبًا كل 3-6 شهور"],"care":[["قبل","يفضل تناول وجبة خفيفة وشرب كمية مناسبة من المياه قبل الجلسة، إلا لو العيادة أعطت تعليمات مختلفة"],["قبل","إبلاغ الدكتور عن أي أدوية تؤثر على النزيف أو الصفائح، وممنوع إيقاف Aspirin أو أي دواء موصوف من الطبيب من تلقاء العميل نفسه"],["بعد","ممكن يحصل احمرار أو تورم خفيف لمدة يوم أو يومين، وممكن تظهر كدمات بسيطة أو ما يحصلش أي كدمات"],["بعد PRP الشعر","يفضل عدم غسل الشعر 12 ساعة على الأقل، وتجنب الصبغة والمواد الكيميائية على الشعر حوالي 3 أيام"]],"say":[["هو آمن؟","لأنه بيتحضر من دمك أنت، فاحتمال الحساسية من مادة البلازما نفسها منخفض، لكن زي أي إجراء طبي ممكن يكون له آثار جانبية أو مخاطر، والدكتور بيقيّم حالتك قبل الجلسة"],["هينبت شعر جديد؟","الـ PRP ممكن يساعد في تقليل التساقط وتحسين حالة وكثافة الشعر عند بعض الحالات، لكن النتيجة بتعتمد على سبب التساقط وحالة البصيلات، ومش بيعيد تكوين بصيلات شعر مفقودة بشكل كامل"],["إيه الفرق بين الـ PRP العادي والـ Zoom؟","فيه أنواع مختلفة من الأنابيب والبروتوكولات، وبعض أنواع Zoom مصممة لاستخدامات معينة أو فيها مكونات إضافية حسب النوع، والدكتور هو اللي بيحدد الأنسب للحالة"],["ينفع آخد الـ Package جلسة شعر وجلستين بشرة؟","الـ Package مخصص لـ 3 جلسات من نفس النوع، ومش بيتقسم بين أنواع مختلفة. لو محتاجة علاج للشعر والبشرة، أقدر أوضحلك أسعار كل نوع"]],"escalate":"تورم أو كدمة كبيرة بتزيد، ألم شديد أو متزايد، سخونية واضحة في مكان الحقن، احمرار بيزيد بدل ما يتحسن، صديد أو إفرازات، أو أي أعراض غير معتادة أو شديدة","review":["إيه الفرق بين Zoom Biotin وZoom HA؟","الباكدج بتاع الـ PRP بيتكون من إيه؟","إيه اللي بتقوله للعميل قبل الجلسة بخصوص الأكل؟","عميلة عايزة الـ Package جلسة شعر وجلستين وش، ترد تقول إيه؟"]}'::jsonb, 12);
insert into public.kb_articles (slug, kind, title, body, sort) values ('service:gcell', 'service', 'G-Cell (بديل زراعة الشعر) - Hair Transplant Alternative', '{"id":"gcell","name":"G-Cell (بديل زراعة الشعر) - Hair Transplant Alternative","branch":"الجهاز في فرع القاهرة الجديدة، والحجز يبدأ من أي فرع","summary":"إجراء يعتمد على عينة صغيرة جدًا من فروة رأس العميل نفسه. بيتم تجهيز العينة بجهاز مخصص لاستخلاص خلايا ومواد حيوية، وبعدها بيتم حقنها في المناطق اللي فيها خفة شعر، بهدف دعم بيئة فروة الرأس وتحفيز نمو الشعر. الطبيب هو اللي بيحدد إذا الحالة مناسبة بعد فحص فروة الرأس.","details":[["مناسب لمين","حالات خفة الشعر وتساقطه، خصوصًا التساقط الوراثي في المراحل المبكرة أو المتوسطة، الرجال والنساء بعد تقييم الحالة، والحالات اللي بتحتاج دعم لنمو الشعر بدون إجراء زراعة شعر جراحية"],["الجلسة شاملة إيه","جلسة G-Cell + 3 جلسات Golden PRP + خصم 20% على علاجات الشعر حسب العروض والشروط الحالية"],["مدة الجلسة","حوالي ساعة إلى ساعة ونصف، مع تخدير موضعي حسب تقييم الطبيب"],["النتيجة","ممكن يلاحظ العميل انخفاض في التساقط خلال الأسابيع التالية، وتحسن الكثافة ومظهر الشعر بيكون تدريجي وغالبًا يحتاج 3-6 شهور لملاحظة النتائج بشكل أوضح — ممنوع نقول إن النتيجة مضمونة أو إن الشعر هيرجع بالكامل"],["مش مناسب لـ / يحتاج تقييم دكتور","منطقة صلعاء تمامًا من غير بصيلات قابلة للاستفادة، التهاب أو عدوى نشطة في فروة الرأس، بعض أمراض الدم أو المناعة، والحمل. لو الحالة مش واضحة: كشف Dermatology + Dermoscope الأول"]],"products":[],"booking":["لازم العميل يعمل كشف بالديرماسكوب قبل G-Cell علشان الدكتور يقيّم فروة الرأس ويحدد إذا الحالة مرشحة","الجهاز متاح في فرع التجمع الخامس، والعميل يقدر يبدأ الحجز من أي فرع، وبعد تأكيد الموعد مع الـ Sales بيتم ترتيب نقل الجهاز للفرع المطلوب","السعر موحد حسب سياسة الباكدج الحالية، والباكدج تشمل G-Cell + 3 Golden PRP + خصم 20% على علاجات الشعر"],"care":[["قبل","التأكد إن العميل عمل Dermoscope/كشف شعر، والتأكد من ترشيح الدكتور لـ G-Cell، وتأكيد الموعد مع الـ Sales"],["بعد","مكان أخذ العينة صغير جدًا وغالبًا غير واضح وسط الشعر، وممكن يحصل احمرار أو ألم بسيط في مكان العينة أو الحقن ليوم أو يومين"],["بعد","عدم غسل الشعر 24 ساعة أو حسب تعليمات الطبيب، وتجنب الصبغة والمواد الكيميائية على الشعر حوالي أسبوع"],["بعد","تجنب الساونا والرياضة العنيفة لعدة أيام، والتأكد من حجز 3 جلسات Golden PRP الموجودة ضمن الباكدج"]],"say":[["هو زي زراعة الشعر؟","لأ، G-Cell مختلف عن زراعة الشعر الجراحية. هو إجراء يعتمد على عينة من فروة رأس العميل نفسه وحقنها في المناطق المستهدفة، والطبيب هو اللي بيحدد إذا كان مناسب للحالة"],["هيبان مكان العينة؟","العينة صغيرة جدًا وبتتاخد من خلف الرأس، وغالبًا بيكون مكانها غير واضح وسط الشعر"],["أنا في المنصورة، لازم أروح التجمع؟","مش بالضرورة، تقدر تبدأ الحجز من الفرع، وبعد تأكيد الموعد بيتم التنسيق مع الـ Sales بخصوص مكان الجلسة ونقل الجهاز"],["السعر شامل إيه؟","الباكدج تشمل G-Cell + 3 جلسات Golden PRP + خصم 20% على علاجات الشعر حسب الشروط الحالية"],["أنا أصلع خالص من قدام، ينفع؟","لو المنطقة مفيهاش بصيلات قابلة للاستفادة، ممكن تكون خيارات أخرى أنسب، والدكتور هو اللي يحدد بعد فحص فروة الرأس بالديرماسكوب"],["إمتى هبدأ أشوف نتيجة؟","النتيجة تدريجية، ممكن يقل التساقط خلال الأسابيع الأولى، وتحسن الكثافة بيحتاج وقت أطول وغالبًا بيظهر بشكل أوضح خلال 3-6 شهور حسب الحالة"]],"escalate":"سخونية واضحة أو مستمرة، صديد أو إفرازات، احمرار بيزيد بدل ما يقل، ألم شديد أو متزايد، تورم شديد أو غير معتاد، أو أي أعراض مقلقة في مكان العينة أو الحقن","review":["الـ G-Cell شامل إيه غير الجلسة نفسها؟","عميل في طنطا عايز G-Cell، إيه الخطوات؟","عميل أصلع خالص من قدام وسأل ينفع G-Cell؟ ترد تقول إيه؟"]}'::jsonb, 13);
insert into public.kb_articles (slug, kind, title, body, sort) values ('service:threads', 'service', 'الخيوط التجميلية (PDO / Cosmetic Threads)', '{"id":"threads","name":"الخيوط التجميلية (PDO / Cosmetic Threads)","branch":"متاحة في كل الفروع","summary":"خيوط طبية قابلة للتحلل، بتتحط تحت الجلد بهدف شد ورفع بعض المناطق وتحفيز إنتاج الكولاجين. بتستخدم في حالات الترهل البسيط إلى المتوسط حسب تقييم الطبيب.","details":[["الاستخدامات","رفع الخدود، تحديد وتحسين شكل خط الفك، تخفيف ترهل الرقبة، تحسين مظهر الغبغب، رفع الحاجب (Fox Eyes) حسب الحالة، وشد وتحسين بعض مناطق الجسم حسب تقييم الطبيب. نوع الخيط ومكان استخدامه بيختلف حسب المنطقة وحالة العميل"],["أنواع الخيوط","خيوط الشد: فيها أجزاء مصممة للمساعدة في تثبيت الأنسجة ورفعها. الخيوط الناعمة: بتستخدم أساسًا لتحسين جودة الجلد وتحفيز الكولاجين، ومش هدفها الأساسي شد قوي للأنسجة"],["مدة الجلسة","حوالي 30 دقيقة لساعة حسب المنطقة وعدد الخيوط، مع تخدير موضعي حسب تقييم الطبيب"],["النتيجة","ممكن يظهر تأثير الشد بعد الإجراء مباشرة، والتحسن ممكن يستمر تدريجيًا خلال الأسابيع التالية مع تحفيز الكولاجين، وبتختلف حسب نوع الخيط والمنطقة وعدد الخيوط وحالة البشرة"],["مدة التأثير","غالبًا يستمر لفترة تختلف حسب النوع والحالة، وقد تكون في حدود 12-18 شهر لبعض أنواع الخيوط — ممنوع نقول للعميل إن النتيجة هتستمر مدة محددة بشكل مضمون"],["مش مناسب لـ / يحتاج تقييم دكتور","الحمل والرضاعة، وجود التهاب أو عدوى نشطة في المنطقة، وجود مشاكل جلدية نشطة في مكان الإجراء، والترهل الشديد جدًا اللي قد يحتاج تدخل جراحي، وأي حالة أخرى يحدد الطبيب إنها غير مناسبة للخيوط"]],"products":[],"booking":["السعر المكتوب هو سعر الخيط الواحد وهو سعر بداية","لما العميل يسأل عن السعر: «سعر الخيط بيبدأ من كذا، والعدد والنوع بيتحددوا بعد استشارة الدكتور حسب الحالة»","⚠️ ما نحسبش للعميل إجمالي تكلفة الخيوط على التليفون؛ نوع الخيط بيتحدد بعد الكشف، وعدد الخيوط بيتحدد حسب المنطقة ودرجة الترهل، والطبيب بيحدد الخطة المناسبة","الخيوط التجميلية متاحة في كل الفروع"],"care":[["قبل","يفضل إبلاغ الطبيب بأي أدوية أو مكملات يتناولها العميل، وأي حساسية أو مشاكل صحية مهمة. الطبيب يحدد أي تعليمات إضافية قبل الإجراء حسب الحالة"],["أول أسبوع","تجنب فتح الفم بشكل مبالغ فيه، وتجنب تعبيرات الوجه القوية، وتجنب الأكل اللي يحتاج مضغ قوي، وتجنب الساونا والرياضة العنيفة، والالتزام بتعليمات الطبيب"],["أول أسبوعين","تجنب تدليك الوجه، وتجنب علاجات الأسنان إلا بعد الرجوع للطبيب"],["طبيعي يحصل","تورم بسيط، زرقان أو كدمات، إحساس بالشد، ألم أو عدم راحة بسيطة، وممكن يظهر تكسير أو تموج بسيط في الجلد ويختفي تدريجيًا"],["النوم","يفضل النوم على الظهر في الفترة الأولى حسب تعليمات الطبيب"]],"say":[["هحتاج كام خيط؟","ده بيتحدد في الاستشارة حسب المنطقة ودرجة الترهل ونوع الخيط. سعر الخيط بيبدأ من كذا، والدكتور بيحدد العدد النهائي بعد الكشف"],["زي شد الوش بالجراحة؟","لا، الخيوط إجراء غير جراحي، وممكن تكون مناسبة لبعض حالات الترهل البسيط والمتوسط. لو الترهل شديد، الدكتور بيقيّم الحالة ويحدد الخيار الأنسب"],["الخيوط بتفضل جوه؟","الخيوط المستخدمة قابلة للتحلل وبتتحلل تدريجيًا حسب نوعها، بينما تأثير تحفيز الكولاجين ممكن يستمر بعد تحلل الخيط"],["خيوط ولا فيلر؟","الاتنين مختلفين: الفيلر بيستخدم أساسًا لتعويض أو إضافة حجم وتحديد بعض المناطق، والخيوط هدفها الأساسي شد ورفع بعض الأنسجة وتحفيز الكولاجين. وفي بعض الحالات ممكن الطبيب يجمع بين أكتر من إجراء حسب احتياج الحالة"],["ممكن أعرف السعر من غير استشارة؟","نقدر نقول سعر بداية الخيط الواحد، لكن ما نقدرش نحدد العدد أو التكلفة الإجمالية قبل ما الدكتور يشوف الحالة"]],"escalate":"ألم بيزيد بدل ما يقل، سخونية أو احمرار متزايد، إفرازات أو صديد، تورم شديد أو متزايد، طرف خيط ظاهر أو خارج من الجلد، أو تغير واضح وغير معتاد في لون الجلد","review":["الخيوط متاحة فين؟","السعر بيتحسب إزاي؟ ومين بيحدد النوع والعدد؟","أقدر أقول للعميل التكلفة النهائية على التليفون؟","عميل عنده ترهل شديد جدًا وعايز خيوط، تعمل إيه؟"]}'::jsonb, 14);
insert into public.kb_articles (slug, kind, title, body, sort) values ('service:hifu', 'service', 'الهايفو (HIFU)', '{"id":"hifu","name":"الهايفو (HIFU)","branch":"متاح في فرع طنطا ٢ - سعيد فقط، والجهاز لا ينتقل بين الفروع","summary":"الهايفو بيستخدم موجات فوق صوتية مركزة بتوصل لطبقات عميقة تحت الجلد، وبتحفز إنتاج الكولاجين، وده بيساعد على شد وتحسين مظهر ترهل البشرة من غير جراحة أو حقن.","details":[["المناطق","الوجه، الوجه والرقبة، الرقبة، الدبل تشين، والبطن"],["عدد الجلسات","غالبًا جلسة واحدة، وممكن الدكتور يوصي بجلسة إضافية حسب الحالة والاستجابة. جلسات المتابعة أو الصيانة بيحددها الدكتور حسب الحالة. ما نحددش للعميل من البداية إنه محتاج عدد جلسات معين"],["مدة الجلسة","من 30 لـ 90 دقيقة تقريبًا، حسب المنطقة وعدد الخطوط المستخدمة"],["الإحساس أثناء الجلسة","وخز بسيط أو متوسط، إحساس بالحرارة أو الطاقة في عمق الجلد، ودرجة الإحساس بتختلف من شخص للتاني"],["النتيجة","ممكن يظهر شد بسيط بعد الجلسة، والتحسن الأساسي بيظهر بشكل تدريجي خلال حوالي 2-3 شهور، وممكن تستمر النتيجة حوالي سنة أو أكتر حسب الحالة — ممنوع نقول إن النتيجة مضمونة لمدة محددة"],["عدد الخطوط والتسعير","كل منطقة ليها حد أقصى من الخطوط ضمن السعر الأساسي: الوجه 100 خط، الوجه والرقبة 150 خط، الرقبة 75 خط، الدبل تشين 50 خط، البطن 500 خط"],["خطوط إضافية","Face Tip: الخط الإضافي = 25 جنيه. Body Tip: كل 100 خط إضافي = 750 جنيه. الزيادة ما بيحددهاش الـ Agent؛ الدكتور هو اللي بيحدد إذا كانت الحالة محتاجة خطوط إضافية"],["مش مناسب لـ / لازم نبلغ الدكتور","الحمل، وجود Pacemaker أو جهاز إلكتروني مزروع، وجود معادن أو زرعات في منطقة العلاج، وجود جروح أو التهاب نشط أو حبوب نشطة بالمنطقة، ووجود فيلر حديث في نفس المنطقة"]],"products":[],"booking":["متاح في طنطا شارع السعيد فقط، والجهاز لا ينتقل لأي فرع آخر — لازم العميل يعرف مكان الخدمة قبل تأكيد الحجز","كل منطقة ليها أقصى عدد خطوط ضمن السعر الأساسي (شوف تفاصيل الخطوط في details)","الخطوط الإضافية: Face Tip 25 جنيه للخط، Body Tip 750 جنيه لكل 100 خط، وبيحددها الدكتور أثناء الجلسة","⚠️ في الحالات اللي محتاجة تقييم طبي (Pacemaker، معادن مزروعة، فيلر حديث، التهاب) ما نديش موافقة من نفسنا؛ يتم الرجوع للدكتور"],"care":[["قبل","اسأل العميل: هل يوجد Pacemaker أو جهاز إلكتروني مزروع؟ هل يوجد أي معدن أو زرعة في منطقة العلاج؟ هل تم عمل فيلر حديث في نفس المنطقة؟ هل يوجد التهاب أو جروح أو حبوب نشطة في المنطقة؟"],["قبل","لو فيه أي نقطة غير واضحة، تحويل للدكتور قبل تأكيد الخدمة"],["بعد","ممكن يحصل احمرار بسيط، تورم خفيف، ألم بسيط عند اللمس، أو تنميل بسيط لفترة مؤقتة، وغالبًا يقدر العميل يمارس نشاطه اليومي بشكل طبيعي حسب تقييم الدكتور"]],"say":[["الهايفو بيعمل إيه؟","بيستخدم موجات فوق صوتية مركزة بتوصل لطبقات عميقة تحت الجلد وبتحفز الكولاجين، وده بيساعد على شد وتحسين مظهر البشرة من غير جراحة أو حقن"],["متاح في فرعي؟","الهايفو متاح حاليًا في فرع طنطا شارع السعيد فقط، والجهاز مابيتنقلش بين الفروع"],["هشوف النتيجة إمتى؟","ممكن تلاحظي شد بسيط بعد الجلسة، لكن التحسن الأساسي بيظهر تدريجيًا خلال حوالي شهرين لـ 3 شهور"],["ليه السعر ممكن يزيد؟","كل منطقة ليها عدد خطوط محدد داخل السعر، ولو الدكتور شاف إن الحالة محتاجة خطوط إضافية، الزيادة بتتحسب حسب عدد الخطوط المستخدمة"],["لو احتجت خطوط زيادة بكام؟","في الـ Face Tip الخط الإضافي بـ 25 جنيه، وفي الـ Body Tip كل 100 خط إضافي بـ 750 جنيه"],["الهايفو ولا الخيوط؟","كل إجراء له استخدام وطريقة مختلفة، والأنسب بيتحدد حسب درجة الترهل والحالة، والدكتور يقدر يحددلك الاختيار المناسب بعد التقييم"],["ممكن أعمله في التجمع؟","الهايفو متاح حاليًا في طنطا شارع السعيد فقط، والجهاز غير متاح في التجمع"]],"escalate":"حرق أو فقاقيع، علامات أو تغير واضح وغير معتاد في الجلد، تنميل مستمر أو متزايد، ضعف في حركة عضلات الوجه، أو ألم شديد أو متزايد بشكل غير معتاد","review":["الهايفو متاح فين؟ وليه الجهاز ما بينتقلش؟","إيه اللي لازم تسأل عنه قبل جلسة الهايفو؟","عميل احتاج خطوط زيادة في جلسة وجه، ازاي بيتحسب السعر؟"]}'::jsonb, 15);
insert into public.kb_articles (slug, kind, title, body, sort) values ('service:dermapen', 'service', 'الديرمابن (Dermapen 4 والعادي)', '{"id":"dermapen","name":"الديرمابن (Dermapen 4 والعادي)","branch":null,"summary":"جهاز Microneedling بيعمل فتحات دقيقة جدًا في الجلد بعمق محسوب، وده بيساعد البشرة على التجدد وتحفيز الكولاجين. بيُستخدم مع مواد إضافية حسب البروتوكول زي PRP والميزوثيرابي والإكزوزومز والـ PDRN وسيرومات مخصصة.","details":[["الاستخدامات","آثار الحبوب، المسام الواسعة، الخطوط الرفيعة، بهتان البشرة، التصبغات الخفيفة، وStretch Marks/الشقوق — النتيجة وعدد الجلسات بيختلفوا حسب الحالة ونوع المشكلة"],["بيتعمل مع إيه","الديرمابن عندنا بيتم مع مادة إضافية زي PRP أو الميزوثيرابي أو الإكزوزومز أو PDRN أو سيرومات مخصصة حسب البروتوكول، والمادة المناسبة بيحددها الدكتور"],["أنواع الديرمابن","Dermapen 4: أحدث من العادي، بيستخدم Needle مخصص سعره 2200 جنيه. Derma Pen العادي: بـ 12 أو 36 إبرة، سعر الـ Needle 150 جنيه (نفس السعر للاتنين). الدكتور هو اللي بيحدد النوع والـ Needle المناسب"],["عدد الجلسات","غالبًا من 3-6 جلسات، بفاصل حوالي 4-6 أسابيع، والعدد النهائي بيتحدد حسب حالة البشرة والمشكلة واستجابتها والمادة المستخدمة"],["مدة الجلسة","حوالي 45 دقيقة لساعة، شاملة وقت الكريم المخدر"],["فترة التعافي","احمرار يشبه لسعة الشمس من يوم لـ 3 أيام، جفاف بسيط، وقشور خفيفة، وبتختلف حسب عمق الجلسة وحالة البشرة"],["مش مناسب لـ / لازم نبلغ الدكتور","حب الشباب الملتهب والنشط، الهربس النشط، الإكزيما أو الالتهاب النشط في المنطقة، وجود ميل لتكوين Keloids، والحمل — وفي حالة حب شباب نشط ما نحددش من نفسنا إن VIVACE هو البديل المناسب، بيتم الرجوع للدكتور"]],"products":[],"booking":["استخدام جهاز الديرمابن نفسه مجاني طالما العميلة عندها الـ Needle الخاصة بيها وبتستخدمها للجلسة","أول جلسة: الفاتورة = سعر الـ Needle + سعر المادة المستخدمة","الجلسات التالية: العميلة لا تدفع سعر الـ Needle مرة أخرى، وتدفع سعر المادة المستخدمة فقط","Dermapen 4 Needle = 2200 جنيه (أول مرة). Derma Pen العادي 12 أو 36 Needle = 150 جنيه (أول مرة)","⚠️ الـ Needle مخصصة للعميلة نفسها ولا يتم مشاركتها مع عميلة أخرى"],"care":[["قبل","لو دي مش أول جلسة، فكّر العميلة تجيب الـ Needle الخاصة بيها، واسأل عن وجود التهاب أو حب شباب نشط أو هربس في المنطقة"],["قبل","لو فيه حالة طبية أو دواء مش واضح تأثيره على الإجراء، يتم الرجوع للدكتور"],["بعد","عدم وضع المكياج 24 ساعة، وتجنب Retinol والأحماض والمقشرات 3-5 أيام حسب تعليمات الدكتور"],["بعد","تجنب الساونا والسباحة 48 ساعة، واستخدام مرطب لطيف وSunscreen، وعدم فرك أو تقشير البشرة بعنف"]],"say":[["الديرمابن بكام؟","الجهاز نفسه مجاني، وبتدفعي تمن الـ Needle أول مرة بس، والـ Needle بتفضل معاكي وتجيبيها في كل جلسة، وبعد كده بتدفعي سعر المادة اللي الدكتور هيختارها للجلسة"],["سعر الـ Needle كام؟","لو Dermapen 4 سعر الـ Needle 2200 جنيه، ولو الديرمابن العادي سعر الـ Needle 150 جنيه، سواء 12 إبرة أو 36 إبرة"],["أنا عملت جلسة قبل كده، هدفع الـ Needle تاني؟","لا، لو معاكي الـ Needle الخاصة بيكي، بتجيبيها معاكي في كل جلسة ومش بتدفعي تمنها مرة تانية"],["نسيت الـ Needle بتاعتي","الـ Needle بتكون مخصصة ليكي، ولو مش معاكي وقت الجلسة ممكن تحتاجي Needle جديدة، وبيتم حساب سعرها"],["الديرمابن بيتعمل لوحده؟","الديرمابن عندنا بيتم مع مادة إضافية حسب البروتوكول، زي الميزوثيرابي أو الإكزوزومز أو PDRN أو غيرها، والدكتور بيحدد المادة المناسبة"],["هو زي الديرمارولر؟","الاتنين بيشتغلوا بتقنية الـ Microneedling، لكن الديرمابن جهاز بإبر دقيقة وبيسمح بالتحكم في العمق حسب المنطقة والبروتوكول"]],"escalate":"احمرار شديد أو متزايد، سخونية واضحة في المنطقة، ألم شديد أو متزايد، إفرازات أو صديد، تورم شديد، أو ظهور حبوب أو التهاب بشكل واضح بعد الجلسة بأيام","review":["الفاتورة في جلسة الديرمابن بتتكون من إيه؟","مين صاحب النيدل، ويتعمل بيه إيه بعد الجلسة؟","لو العميلة نسيت الـ Needle بتاعتها، تعمل إيه؟"]}'::jsonb, 16);
insert into public.kb_articles (slug, kind, title, body, sort) values ('service:vivace', 'service', 'الفيفاتشي VIVACE', '{"id":"vivace","name":"الفيفاتشي VIVACE","branch":"متاح في فرع القاهرة الجديدة فقط","summary":"جهاز Microneedling + RF، بيستخدم إبر دقيقة جدًا مع طاقة Radiofrequency بشكل محكوم داخل الجلد، وده بيساعد على تحفيز الكولاجين وتحسين شد وملمس البشرة.","details":[["الاستخدامات","ترهل وارتخاء البشرة، تحسين مظهر المسام، آثار حب الشباب، الخطوط الرفيعة، تحسين تحديد الفك، الرقبة، منطقة الـ Décolleté، وبعض حالات حب الشباب النشط باستخدام الـ TIP المخصص حسب تقييم الطبيب"],["عدد الجلسات","غالبًا 3 جلسات بفاصل حوالي 4-6 أسابيع، وبعدها ممكن جلسات صيانة حسب حالة البشرة وتقييم الطبيب"],["مدة الجلسة","حوالي ساعة، منها حوالي 30 دقيقة لكريم التخدير"],["فترة التعافي","احمرار أو تورم خفيف من 1-3 أيام، وممكن تظهر نقط صغيرة مكان الإبر، وبتختلف حسب شدة الجلسة واستجابة البشرة"],["النتيجة","ممكن تظهر نضارة وتحسن أولي خلال فترة قصيرة، وتحسن الملمس والشد بيظهر تدريجيًا مع تحفيز الكولاجين وقد يستمر يتحسن خلال الأسابيع والشهور التالية"],["الـ TIP","مخصص لكل مريضة، سعره 2000 جنيه، بتشتريه مرة واحدة وتجيبه معاها في كل جلسة لاحقة. لو معاها الـ TIP الخاص بيها، مش بتدفع تمن TIP جديد"],["مش مناسب لـ / بلّغ الدكتور","الحمل، وجود Pacemaker أو جهاز إلكتروني مزروع، وجود معادن أو أجهزة مزروعة في منطقة العلاج، التهاب أو عدوى جلدية نشطة (باستثناء حالات ممكن التعامل معها بالـ TIP المخصص بعد تقييم الطبيب)، الميل الشديد لتكوين Keloid، وأي حالة جلدية نشطة أو غير واضحة"]],"products":[],"booking":["جلسة واحدة + المريضة معها الـ TIP = 2000 جنيه","3 جلسات + المريضة معها الـ TIP = 4000 جنيه","أول جلسة بدون TIP سابق = 4000 جنيه (شامل الـ TIP)","باكدج 3 جلسات + TIP جديد = 5500 جنيه","لو العميلة هتعمل VIVACE مع Exosomes أو Mesotherapy أو PRP، يتم إضافة سعر المادة/الخدمة الإضافية حسب مكتب الأسعار","متاح في فرع التجمع الخامس فقط، لازم العميل يعرف ده قبل الحجز"],"care":[["قبل","اسأل العميلة عن وجود Pacemaker أو أي جهاز إلكتروني مزروع، وعن وجود معادن أو أجهزة مزروعة في منطقة العلاج وسجل المعلومة"],["قبل","إبلاغ الطبيب بأي أدوية أو علاجات جلدية حالية، وأي التهاب أو مشكلة جلدية موجودة في منطقة العلاج"],["بعد","تجنب المكياج 24 ساعة أو حسب تعليمات الطبيب، وتجنب الـ Retinol والأحماض والمقشرات القوية 3-5 أيام"],["بعد","تجنب الساونا والرياضة العنيفة حوالي 48 ساعة، والالتزام بواقي الشمس، وعدم فرك أو حك الجلد"]],"say":[["متاح في فرعي؟","الـ VIVACE متاح في فرع التجمع الخامس فقط، تحبي أحجزلك هناك؟"],["ليه أول جلسة أغلى؟","لأن أول مرة بيتم شراء الـ TIP الخاص بيكي، وسعره 2000 جنيه وبيفضل معاكي وتجيبيه في الجلسات التالية"],["عندي حبوب دلوقتي، ينفع؟","الجهاز عنده TIP مخصص للحالات اللي فيها حب شباب نشط، لكن الدكتور بيحدد إذا كان مناسب لحالتك ونوع الجلسة بعد تقييم البشرة"],["إيه الفرق بينه وبين الديرمابن؟","الاتنين بيعتمدوا على Microneedling، لكن الـ VIVACE بيضيف Radiofrequency (RF) داخل الجلد، وده بيضيف تحفيز حراري للكولاجين بجانب تأثير الإبر"]],"escalate":"حرق واضح أو فقاقيع، ألم شديد أو بيزيد، سخونية شديدة في المنطقة، صديد أو إفرازات، احمرار شديد أو متزايد ومستمر، أو تورم شديد أو غير معتاد","review":["الـ VIVACE متاح فين؟ والتيب بتاع مين؟","إيه السؤال اللي لازم تسأله قبل الجلسة بخصوص القلب؟","عميلة معاها TIP خاص بيها، هتدفع تمنه تاني في الجلسة التالية؟"]}'::jsonb, 17);
insert into public.kb_articles (slug, kind, title, body, sort) values ('service:cleansing', 'service', 'جلسات تنظيف البشرة (Facial Cleansing)', '{"id":"cleansing","name":"جلسات تنظيف البشرة (Facial Cleansing)","branch":"الأجهزة مش متاحة في كل الفروع — OxyGeneo في شبين وطنطا ٢ - سعيد بس، وSkin Cleansing (تنظيف بشرة عادي) في طنطا ١ - الاستاد بس","summary":"جلسات بتساعد على إزالة الدهون الزائدة والشوائب والرؤوس السوداء والبيضاء والجلد الميت، مع ترطيب البشرة وتحسين شكلها ونضارتها. مناسبة لمعظم أنواع البشرة، لكن لو فيه التهاب شديد أو مشكلة جلدية نشطة، الأفضل تقييم الحالة عند دكتور جلدية الأول.","details":[["الأنواع المتاحة","Steam Facial (تنظيف بالبخار)، Facial (تنظيف بشرة تقليدي)، HydraFacial (تنظيف وتقشير وشفط شوائب مع سيرومات ترطيب)، OxyGeneo (تقشير خفيف وتنظيف مع سيرومات ومنتجات مخصصة)، وAqua Pure (تنظيف وترطيب بالجهاز)"],["خطوات الجلسة","حسب النوع: تنظيف البشرة، تقشير خفيف، بخار حسب نوع الجلسة، تنظيف الرؤوس والشوائب، سيرومات، ماسك، ومرطب وواقي شمس"],["مدة الجلسة","من 45 دقيقة لساعة وربع تقريبًا، حسب نوع الجلسة"],["التكرار","غالبًا كل 3-4 أسابيع، حسب نوع البشرة واحتياجها وتعليمات المختص"],["مش مناسب لـ / يحتاج تقييم الأول","حب الشباب الملتهب بشدة، التهاب أو عدوى جلدية نشطة، جروح أو تهيج شديد في البشرة، حروق الشمس، وأي حالة جلدية نشطة تحتاج تقييم طبي"],["توفر الأنواع بالفرع","OxyGeneo: متاح في شبين وطنطا ٢ - سعيد فقط. Skin Cleansing (تنظيف عادي): متاح في طنطا ١ - الاستاد فقط. لازم تتأكد من توفر النوع المطلوب في فرع العميل قبل تأكيد الحجز"]],"products":[],"booking":["⚠️ OxyGeneo متاح في شبين وطنطا ٢ - سعيد بس، وSkin Cleansing (التنظيف العادي) متاح في طنطا ١ - الاستاد بس — تأكد من الفرع قبل الحجز","الأجهزة مش موجودة في كل الفروع؛ لازم تتأكد من توفر الجهاز في فرع العميل قبل تأكيد الحجز","HydraFacial وOxyGeneo وAqua Pure: السعر حسب مكتب الأسعار والسياسة الحالية","OxyGeneo: أول جلسة بكبسولة جديدة، والجلسة التالية حسب السياسة الحالية بدون كبسولة جديدة وبسعر أقل"],"care":[["قبل","يفضل الحضور بدون مكياج، وإبلاغ المختص بأي حساسية أو تهيج أو علاج جلدي حالي"],["قبل","لو فيه حب شباب ملتهب جدًا أو التهاب واضح، يفضل كشف جلدية قبل جلسة التنظيف"],["بعد","ممكن يحصل احمرار خفيف أو حساسية بسيطة لفترة قصيرة، ويفضل تجنب المكياج الثقيل باقي اليوم لو البشرة متهيجة"],["بعد","تجنب الـ Scrubs والمقشرات القوية حوالي 48 ساعة أو حسب تعليمات المختص، واستخدام واقي الشمس"],["بعد","لو البشرة محتاجة متابعة، ممكن اقتراح الجلسة التالية بعد حوالي 3-4 أسابيع"]],"say":[["إيه الفرق بين التنظيف العادي والهيدرافيشيال؟","الهيدرافيشيال بيستخدم جهاز لتنظيف وتقشير البشرة وشفط الشوائب مع الترطيب والسيرومات، أما التنظيف العادي فبيعتمد على خطوات تنظيف تقليدية. اختيار الأنسب بيختلف حسب حالة البشرة"],["إيه الفرق بين الهيدرافيشيال والأكسجينيو؟","الاتنين جلسات أجهزة، لكن كل جهاز له طريقة مختلفة في التنظيف والتقشير والسيرومات المستخدمة، والمختص يقدر يرشح الأنسب حسب احتياج بشرتك"],["عندي فرح بكرة، أعمل تنظيف؟","الأفضل تعملي الجلسة قبل المناسبة بعدة أيام، لأن أي جلسة تنظيف ممكن تسبب احمرار أو حساسية مؤقتة حسب البشرة، ولو المناسبة قريبة جدًا الأفضل اختيار الجلسة المناسبة بعد تقييم البشرة"],["أعملها كل قد إيه؟","غالبًا كل 3-4 أسابيع، لكن المدة المناسبة بتختلف حسب نوع بشرتك واحتياجها"]],"escalate":"التهاب شديد أو متزايد، تورم واضح، ألم شديد، فقاقيع أو حروق، إفرازات أو صديد، أو تهيج شديد ومستمر بعد الجلسة. ولو فيه تورم في الوجه أو الشفايف مع صعوبة في التنفس → توجيه للطوارئ فورًا","review":["قبل ما تأكد حجز هيدرافيشيال، لازم تعمل إيه؟","ليه جلسة الأكسجينيو التانية أرخص؟","عميلة عندها فرح بكرة وعايزة تعمل تنظيف بشرة، ترد تقول إيه؟"]}'::jsonb, 18);
insert into public.kb_articles (slug, kind, title, body, sort) values ('service:peeling', 'service', 'التقشير (البارد والكيميائي وحب الشباب) - Chemical Peels', '{"id":"peeling","name":"التقشير (البارد والكيميائي وحب الشباب) - Chemical Peels","branch":null,"summary":"جلسات تقشير بتستخدم مواد بتركيزات طبية للمساعدة في تجديد سطح البشرة وتحسين الملمس واللون، وتقليل بعض التصبغات وآثار حب الشباب السطحية. نوع التقشير بيتحدد حسب المشكلة ونوع البشرة، فيه أنواع ألطف زي بعض أنواع التقشير البارد، وأنواع كيميائية أقوى ممكن يصاحبها احمرار أو تقشير لعدة أيام.","details":[["السعر","الأسعار تبدأ من 500 جنيه، والتكلفة النهائية بتتحدد حسب نوع التقشير والدكتور والكشف"],["دواعي الاستخدام","تحسين ملمس البشرة وتوحيد لونها، المساعدة في تحسين آثار حب الشباب السطحية وتقليل التصبغات والبقع السطحية، الكلف والتصبغات حسب تقييم الطبيب، بعض المناطق الداكنة (الإبط، البكيني، الكوع، الركبة)، والبشرة الباهتة وغير المتجانسة"],["عدد الجلسات","غالبًا من 3-6 جلسات بفاصل حوالي 2-4 أسابيع، لكن البروتوكول النهائي بيحدده الدكتور حسب الحالة ونوع التقشير"],["مدة الجلسة","حوالي 30-45 دقيقة حسب النوع والمنطقة"],["الأنواع المتاحة","تقشير بالمنطقة: Green Peel Medium، RaiMelan، Nanopeel، Normelan. تقشير حب الشباب: Acne Mask/Medium/Forte. تقشير بالبف: Normelan، Retipeel. وكمان Cemazone، وChemical Peels: TCA وSA حسب تقييم الطبيب"],["مش مناسب لـ / بلّغ الدكتور","الحمل والرضاعة، هربس نشط، جروح أو التهاب أو عدوى جلدية نشطة، حروق شمس أو تعرض قوي للشمس مؤخرًا، حساسية معروفة من مكونات المنتج، استخدام Accutane/Isotretinoin حاليًا أو مؤخرًا، وأي تقشير أو إجراء جلدي حديث في نفس المنطقة"]],"products":[],"booking":["الأسعار تبدأ من 500 جنيه، والتكلفة النهائية بتتحدد حسب نوع التقشير والدكتور والكشف","Green Peel وNanopeel وNormelan وRaiMelan: نفس السعر لأي منطقة حسب سياسة الأسعار الحالية","SA وTCA: سعر حسب سياسة الفرع، سواء للمنطقة الكاملة أو للبقع","النوع والتركيز النهائي بيحدده الدكتور، وممنوع نحدد للعميل نوع أو تركيز من نفسنا","التقشير الكيميائي، خصوصًا الأنواع الأقوى، ممكن يسبب احمرار وتقشير لعدة أيام؛ لازم العميل يعرف ده قبل الحجز"],"care":[["قبل","تجنب التعرض المباشر للشمس قدر الإمكان قبل الجلسة، وإبلاغ الدكتور عن استخدام الريتينول أو المقشرات أو أي منتجات نشطة"],["قبل","إبلاغ الدكتور بأي تقشير سابق أو حساسية جلدية، وفي حالة استخدام Accutane/Isotretinoin حاليًا أو مؤخرًا، أو الحمل أو الرضاعة، أو هربس نشط أو أي التهاب/عدوى جلدية"],["بعد التقشير البارد","ممكن يحصل احمرار خفيف أو إحساس بالشد حسب النوع، وغالبًا مفيش فترة تعافي كبيرة لكن الاستجابة بتختلف من بشرة للتانية"],["بعد التقشير الكيميائي","ممكن يحصل احمرار أو تقشير لعدة أيام حسب النوع والتركيز، ممنوع إزالة الجلد المتقشر باليد، واستخدام المرطب والمنتجات المهدئة حسب تعليمات الدكتور"],["بعد","الالتزام بواقي الشمس وتجديده حسب التعليمات، وتجنب الريتينول والأحماض والـ Scrubs لحد ما الدكتور يسمح"]],"say":[["يعني إيه تقشير بارد؟","نوع من أنواع التقشير بيكون ألطف من بعض أنواع التقشير الكيميائي، وبيساعد على تحسين لون وملمس البشرة، وغالبًا وقت التعافي أقل، لكن ده بيختلف حسب النوع والبشرة"],["عندي إبط غامق، فيه حل؟","فيه أنواع تقشير ممكن تتعمل للمناطق الداكنة زي الإبط والبكيني والكوع والركبة، والدكتور بيحدد النوع المناسب بعد تقييم المنطقة"],["عندي كلف، هيشيله؟","التقشير ممكن يساعد في تحسين الكلف، لكن الكلف محتاج تقييم وخطة علاج مناسبة مع الالتزام بواقي الشمس، فالأفضل البدء بكشف جلدية"],["ينفع أعمله في الصيف؟","ده بيختلف حسب نوع التقشير وحالة البشرة، والأهم الالتزام الصارم بالحماية من الشمس، والدكتور بيحدد التوقيت المناسب"]],"escalate":"حرقان شديد أو ألم بيزيد، فقاقيع أو حروق، تورم شديد أو متزايد، إفرازات أو صديد، احمرار شديد ومستمر أو بيزيد، أو ظهور تغير واضح في لون الجلد بعد الجلسة","review":["إيه القاعدة في سعر الـ SA والـ TCA؟","إيه الحاجة اللي لازم العميل يعرفها قبل حجز التقشير الكيميائي؟","عميلة عندها كلف وسألت هيشيله التقشير؟ ترد تقول إيه؟"]}'::jsonb, 19);
insert into public.kb_articles (slug, kind, title, body, sort) values ('service:derma_other', 'service', 'خدمات جلدية تانية (Other Derma)', '{"id":"derma_other","name":"خدمات جلدية تانية (Other Derma)","branch":null,"summary":"خدمات جلدية بيتم تحديدها بعد الكشف وتقييم الحالة: تطعيم السنط (الثآليل)، تسليك الندبات (Subcision)، وحقن Dutasteride للشعر. الخدمات دي ما بتتحجزش كإجراء مؤكد من غير تقييم الطبيب للحالة.","details":[["تطعيم السنط (الثآليل)","إجراء بيهدف لتنشيط استجابة مناعة الجسم ضد السنط، وبيتم تحديد طريقة العلاج وعدد الجلسات حسب حالة السنط ورأي الطبيب. ممكن يحتاج أكتر من جلسة والدكتور بيحدد العدد والفاصل بينهم"],["تسليك الندبات (Subcision)","الطبيب بيستخدم إبرة خاصة لفك الألياف تحت الجلد اللي بتشد الندبة الغائرة لتحت، بهدف تحسين شكلها. ممكن يتعمل منفرد أو يتجمع مع Filler أو PRP أو Fractional Laser CO2 حسب تقييم الطبيب. خصوصًا للندبات الغائرة (Atrophic/Depressed)، ومش كل الندبات مناسبة له. النتيجة تدريجية وقد تحتاج أكتر من جلسة أو إجراء إضافي"],["حقن Dutasteride","حقن في فروة الرأس، قد يستخدمها الطبيب ضمن خطة علاج التساقط الوراثي في الحالات المناسبة. الدكتور بيحدد المناسبة والجرعة والكمية وعدد الجلسات"],["مش مناسب لـ / يحتاج تقييم دكتور","الحمل أو الرضاعة، وجود التهاب أو عدوى نشطة في المنطقة، وجود أمراض أو أدوية مستمرة قد تؤثر على الإجراء. بالنسبة لـ Dutasteride: الحمل أو التخطيط للحمل لازم يتبلغ به الطبيب قبل العلاج"]],"products":[],"booking":["⚠️ الخدمات دي بتتحدد بعد الكشف؛ ما نحجزش الإجراء بشكل مؤكد من غير ما الدكتور يشوف الحالة","بالنسبة لـ Dutasteride: لازم العميل يذكر للطبيب أي حمل أو تخطيط للحمل، والطبيب هو اللي يحدد المناسبة والجرعة وخطة العلاج، وما نديش للعميل جرعة أو مدة علاج من نفسنا"],"care":[["قبل","التأكد من وجود كشف وتقييم طبي، وتسجيل أي معلومات مهمة يذكرها العميل وإبلاغ الطبيب. بالنسبة لـ Dutasteride، التأكد من إبلاغ الطبيب بأي حمل أو تخطيط للحمل"],["بعد تطعيم السنط أو Subcision","ممكن يحصل احمرار بسيط أو تورم أو زرقان في مكان الإجراء، ويلتزم العميل بتعليمات الطبيب للعناية بالمنطقة"],["بعد Dutasteride","يلتزم العميل بتعليمات الطبيب بخصوص غسل الشعر والعناية بفروة الرأس، وما نديش تعليمات إضافية غير معتمدة من الطبيب"]],"say":[["عندي سنط، بتشيلوه إزاي؟","فيه أكتر من طريقة لعلاج السنط، ومنها التطعيم، لكن الدكتور لازم يشوف الحالة الأول ويحدد الطريقة الأنسب"],["الندبة غايرة، فيه حل؟","ممكن يكون Subcision (تسليك الندبات) مناسب لبعض أنواع الندبات الغائرة، وممكن يتعمل مع إجراءات تانية حسب الحالة، والدكتور بيحدد ده بعد الكشف"],["سمعت عن حقن للشعر اسمها Dutasteride","موجودة كخيار علاجي لبعض حالات التساقط الوراثي، لكن لازم كشف الأول لأن مش كل الحالات مناسبة لها"],["ممكن أعمل Dutasteride وأنا بخطط للحمل؟","لازم تبلغي الدكتور بالتخطيط للحمل قبل أي إجراء، والطبيب هو اللي يحدد إذا كان العلاج مناسبًا أم لا"]],"escalate":"سخونية في مكان الحقن، صديد أو إفرازات، احمرار بيزيد أو بينتشر، ألم شديد أو متزايد، تورم شديد أو غير معتاد، أو أي أعراض غير طبيعية أو متزايدة","review":["هل الخدمة محتاجة كشف؟","هل أقدر أأكد الإجراء قبل تقييم الدكتور؟","هل Dutasteride يحتاج مراجعة خاصة للحمل أو التخطيط للحمل؟","هل كل ندبة مناسبة لـ Subcision؟"]}'::jsonb, 20);
insert into public.kb_articles (slug, kind, title, body, sort) values ('service:dental', 'service', 'الأسنان (Dental)', '{"id":"dental","name":"الأسنان (Dental)","branch":"متاحة في فرع طنطا ٢ - سعيد فقط، مع د. علي هشام","summary":"عيادة أسنان متكاملة تشمل الكشف، التنظيف والتجميل، الحشو وعلاج العصب، الخلع، التركيبات، الزراعة، أسنان الأطفال، وليزر اللثة والشفايف. أي علاج بيبدأ بكشف، والدكتور هو اللي بيحدد الخطة والتكلفة النهائية حسب حالة العميل.","details":[["الكشف","الخطوة الأولى قبل تحديد العلاج، والدكتور بيحدد المشكلة والعلاج المناسب وعدد الجلسات والخطة والتكلفة النهائية — ممنوع نأكد تكلفة نهائية قبل الكشف"],["التنظيف والتجميل","تنظيف جير، تلميع الأسنان، تبييض الأسنان، بيرسينج الأسنان (Tooth Gem)، وباكدجات مجمعة حسب الخدمات المتاحة"],["الحشو وعلاج العصب","حشو عادي، حشو تجميلي (Composite)، علاج عصب الأسنان الأمامية أو الضروس — نوع العلاج وعدد الجلسات بيتحدد حسب حالة السن"],["الخلع","خلع عادي أو خلع جراحي، والدكتور بيحدد النوع حسب حالة السن ومكانه"],["التركيبات الثابتة","Porcelain، Zircon، E-Max، Stainless Steel Crown، ودعامات Fiber أو Metal — والدكتور بيحدد الأنسب حسب حالة السن والوظيفة المطلوبة"],["الزراعة","أنواع متعددة: ألماني، أمريكي، إيطالي، كوري، مصري. الدكتور بيقيّم حالة اللثة وكمية وكثافة العظم والسن والمنطقة المطلوبة، وربما الأشعة، وبعدها يحدد النوع والخطة والتكلفة النهائية"],["التركيبات المتحركة","تركيبات متحركة للفكين، Flex، وتركيبات تجميلية Snap-On — النوع المناسب بيتحدد حسب حالة العميل"],["أسنان الأطفال","حافظ مسافة (Space Maintainer) بيستخدم بعد فقدان سن لبني مبكرًا للمساعدة في الحفاظ على المسافة للسن الدائم، والطبيب هو اللي يحدد إذا الطفل محتاجه"],["ليزر اللثة والشفايف","Gingivectomy (قص أو إعادة تشكيل جزء من اللثة)، توريد اللثة، توريد الشفايف (فيه باكدج)، وعلاج التصاق الشفايف باللثة"]],"products":[],"booking":["متاحة في طنطا شارع السعيد فقط مع د. علي هشام؛ لازم توضح للعميل المكان قبل تأكيد الحجز","أي علاج يبدأ بكشف، والسعر النهائي بيحدده الدكتور بعد تقييم الحالة","لو العميل بيسأل عن سعر خدمة معينة، نذكر سعر البداية فقط لو موجود في قائمة الأسعار الحالية — ممنوع نحدد تكلفة علاج نهائية من غير كشف","الأسنان غير متاحة في التجمع أو المنصورة حسب الخدمة الحالية"],"care":[["قبل","يُفضل العميل يجيب معه أي أشعة أسنان قديمة، والروشتات أو الأدوية اللي بيستخدمها، ويبلغ عن أي أدوية سيولة أو أمراض مزمنة"],["بعد الخلع أو الجراحة","يلتزم العميل بتعليمات الدكتور في الأكل والمضمضة والأدوية"]],"say":[["الزراعة بكام؟","تبدأ من سعر حسب نوع الزرعة، وفيه أكتر من نوع، والدكتور هيحدد الأنسب والتكلفة النهائية في الكشف"],["متاح في المنصورة؟","الأسنان في فرع طنطا شارع السعيد فقط مع د. علي هشام، تحبي أحجزلك هناك؟"],["عايزة أبيض سناني","موجود، ولو محتاجة تنظيف كمان فيه باكدج تبييض وتنظيف وتلميع أوفر"]],"escalate":"ورم كبير في الوجه، سخونية، نزيف ما بيقفش، أو صعوبة في البلع أو النفس","review":["الأسنان متاحة فين ومع مين؟","اذكر علامتين طوارئ بعد علاج الأسنان","عميل سأل عن سعر الزراعة، ترد تقول إيه؟"]}'::jsonb, 21);
insert into public.kb_articles (slug, kind, title, body, sort) values ('def:laser', 'definition', 'جلسات الليزر', '{"title":"جلسات الليزر","priceNote":"الأسعار تبدأ من ٥٠٠ جنيه، وعلى حسب تقييم الدكتور والكشف بيحدد التكلفة النهائية.","explain":"الليزر الطبي بيستهدف بصيلات الشعر أو الصبغة في الجلد بطاقة ضوء محددة، فبيقلل الشعر الزائد بشكل تدريجي على جلسات، وبيساعد كمان في بعض مشاكل الجلد زي التصبغات والشعيرات الدموية السطحية. الدكتور هو اللي بيحدد المناسب وعدد الجلسات.","neverSay":["«نهائي» / «مدى الحياة» / «مش هتحتاج جلسات»","«متقلقش من الشمس»"],"indications":["إزالة الشعر الزائد من الجسم والوجه بشكل دائم أو شبه دائم.","تفتيح بعض التصبغات الجلدية السطحية.","علاج توسع الشعيرات الدموية السطحية البسيطة."],"before":["التأكد من عدم وجود تعرض حديث للشمس (يُفضّل تجنبه لمدة أسبوعين قبل الجلسة).","عدم إزالة الشعر بالشمع أو النتف قبل الجلسة بأسبوعين على الأقل (يمكن الحلاقة فقط).","التوقف عن الكريمات المقشرة أو الحساسة للضوء (مثل الريتينول) حسب توجيه الطبيب.","تنظيف المنطقة من أي مكياج أو كريمات أو زيوت قبل الجلسة.","إخبار الطبيب بأي تاريخ مرضي جلدي أو أدوية مؤثرة على حساسية الجلد للضوء."],"after":["تجنب التعرض المباشر للشمس واستخدام واقي شمس عالي الحماية لمدة أسبوعين.","تهدئة الجلد بكمادات باردة أو كريم مهدئ عند الاحمرار أو التهيج البسيط.","تجنب الحمامات الساخنة جدًا أو الساونا لمدة ٢٤-٤٨ ساعة.","عدم استخدام مستحضرات كيميائية قوية (تقشير أو عطور) لعدة أيام.","عدم حك أو خدش المنطقة المعالجة."],"contra":["الحمل والرضاعة (وفق تقييم الطبيب).","وجود عدوى جلدية نشطة أو جروح مفتوحة بمكان العلاج.","التعرض الشديد والحديث للشمس أو حروق الشمس.","بعض الحالات الجلدية المزمنة غير المستقرة (تُقيَّم فرديًا)."]}'::jsonb, 0);
insert into public.kb_articles (slug, kind, title, body, sort) values ('def:botox', 'definition', 'حقن البوتوكس', '{"title":"حقن البوتوكس","priceNote":"اليونيت بـ٩٠ جنيه، وعلى حسب الدكتور والكشف بيحدد عدد الوحدات المستخدمة والتكلفة النهائية.","explain":"حقن دقيقة بتقلل انقباض عضلات معينة في الوجه بشكل مؤقت، فبتنعّم خطوط التعبير زي الجبهة وحوالين العين. وممكن كمان تُستخدم في بعض حالات فرط التعرق الموضعي تحت إشراف الدكتور.","neverSay":["«هتبقى بدون أي خط»","«شكلك هيبقى طبيعي ١٠٠٪»","«ماله ضرر»"],"indications":["تنعيم خطوط وتجاعيد التعبير (الجبهة، حول العينين، بين الحاجبين).","علاج بعض حالات فرط التعرق الموضعي (تحت إشراف طبي).","الوقاية المبكرة من تعمق خطوط التعبير مع التقدم في العمر."],"before":["استشارة طبية مسبقة وتقييم كامل للتاريخ الصحي.","التوقف عن مميعات الدم (مثل الأسبرين) قبل الجلسة حسب توجيه الطبيب.","تجنب الكحوليات قبل الجلسة بيوم على الأقل.","إبلاغ الطبيب بوجود حمل أو رضاعة أو أمراض عصبية أو عضلية.","الوصول بوجه نظيف خالٍ من المكياج."],"after":["تجنب الاستلقاء أو النوم على الوجه ٤ ساعات على الأقل بعد الحقن.","تجنب فرك أو تدليك مناطق الحقن لمدة ٢٤ ساعة.","الامتناع عن الرياضة الشاقة لمدة ٢٤ ساعة.","تجنب الحمامات الساخنة والساونا لمدة يوم على الأقل.","المتابعة مع الطبيب عند استمرار تورم أو كدمات لفترة أطول من المتوقع."],"contra":["الحمل والرضاعة.","أمراض عصبية وعضلية معينة (مثل الوهن العضلي الوبيل).","وجود عدوى أو التهاب بمكان الحقن.","الحساسية المعروفة تجاه البوتولينيوم توكسين."]}'::jsonb, 1);
insert into public.kb_articles (slug, kind, title, body, sort) values ('def:filler', 'definition', 'الفيلر (الحشوات التجميلية)', '{"title":"الفيلر (الحشوات التجميلية)","explain":"حقن مادة مالئة (حمض هيالورونيك) بترجّع حجم مفقود أو بتحدد ملامح زي الشفايف والخدود وخط الفك، وبتنعّم الخطوط العميقة زي اللي حوالين الأنف والفم. الدكتور بيحدد النوع والكمية المناسبة لكل حالة.","neverSay":["«ده بيدوم للأبد»","«مفيش أي خطورة»","«الكدمة دي عادية» (أي عرض بعد الجلسة يتحول للدكتور)"],"indications":["ملء الخدود وإعادة الحجم لمناطق فقدت الامتلاء الطبيعي.","تحديد أو تكبير الشفاه بشكل متناسق.","تنعيم الخطوط العميقة مثل خطوط الأنف والفم.","تحديد ملامح خط الفك والذقن."],"before":["استشارة طبية مسبقة لتحديد نوع ونسبة الفيلر المناسب.","التوقف عن مميعات الدم والمكملات (زيت السمك، فيتامين E) حسب توجيه الطبيب.","تجنب الكحوليات قبل الجلسة بيوم لتقليل فرص الكدمات.","إبلاغ الطبيب بأي تاريخ حساسية أو حقن فيلر سابقة.","تأجيل الجلسة عند وجود التهاب أو عدوى نشطة (مثل الهربس)."],"after":["تجنب الضغط أو التدليك الشديد على مناطق الحقن أول أيام إلا بتوجيه الطبيب.","كمادات باردة عند الحاجة لتقليل التورم أو الكدمات.","تجنب الحرارة الشديدة (ساونا، شمس مباشرة) لمدة أسبوع تقريبًا.","تجنب الرياضة الشاقة لمدة ٢٤-٤٨ ساعة.","المتابعة الفورية مع الطبيب عند شحوب شديد أو ألم غير طبيعي أو تغيّر لون الجلد."],"contra":["الحمل والرضاعة.","اضطرابات تخثر الدم غير المنضبطة.","وجود عدوى نشطة بمكان الحقن.","الحساسية المعروفة تجاه مكونات الفيلر."]}'::jsonb, 2);
insert into public.kb_articles (slug, kind, title, body, sort) values ('def:meso', 'definition', 'الميزوثيرابي', '{"title":"الميزوثيرابي","priceNote":"الأسعار تبدأ من ٤٠٠ جنيه، وعلى حسب الدكتور والكشف بيحدد التكلفة النهائية.","explain":"حقن مزيج من فيتامينات وأحماض أمينية ومغذيات في الطبقات السطحية من الجلد، علشان تحسّن النضارة والترطيب وتقلل مظهر التعب على البشرة.","neverSay":["«بيفتّح البشرة نهائيًا»","«بيشيل التجاعيد»"],"indications":["تحسين نضارة وترطيب البشرة بشكل عام.","تقليل علامات التعب والإرهاق الظاهرة على الجلد.","تحسين ملمس البشرة الباهتة أو المرهقة."],"before":["تنظيف الوجه جيدًا من المكياج والزيوت قبل الجلسة.","إبلاغ الطبيب بأي حساسية تجاه مكونات المحلول.","تجنب المقشرات القوية قبل الجلسة بأيام قليلة.","تأجيل الجلسة عند وجود التهاب جلدي نشط أو حبوب ملتهبة."],"after":["تجنب المكياج مباشرة بعد الجلسة لساعات.","استخدام واقي شمس لحماية البشرة الحساسة مؤقتًا.","تجنب حك أو فرك الوجه بقوة خلال ٢٤ ساعة.","الامتناع عن حمامات السباحة أو الساونا لمدة يوم على الأقل."],"contra":["الحمل والرضاعة (تُقيَّم من الطبيب).","الحساسية من أي من مكونات المحلول.","وجود عدوى أو جروح مفتوحة بمكان العلاج."]}'::jsonb, 3);
insert into public.kb_articles (slug, kind, title, body, sort) values ('def:peeling', 'definition', 'التقشير الكيميائي', '{"title":"التقشير الكيميائي","priceNote":"الأسعار تبدأ من ٥٠٠ جنيه، وعلى حسب الدكتور والكشف بيحدد التكلفة النهائية.","explain":"محاليل كيميائية بتركيز طبي بتزيل الطبقات السطحية من الجلد، علشان تحسّن الملمس واللون وتساعد في آثار حب الشباب السطحية والتصبغات.","neverSay":["«ملوش أي آثار جانبية»","«هتخرج من الجلسة بوش جاهز للمناسبة»"],"indications":["تحسين ملمس البشرة وتوحيد لونها.","المساعدة في علاج آثار حب الشباب السطحية.","تقليل التصبغات والبقع الجلدية السطحية."],"before":["تجنب التعرض المباشر للشمس لمدة أسبوعين قبل الجلسة.","التوقف عن الريتينول أو المقشرات القوية حسب توجيه الطبيب.","إخبار الطبيب بأي تاريخ تقشير سابق أو حساسية جلد.","الوصول ببشرة نظيفة خالية من الكريمات أو المكياج."],"after":["استخدام واقي شمس عالي الحماية يوميًا وبشكل صارم.","تجنب فرك أو تقشير الجلد يدويًا حتى يتقشر طبيعيًا.","استخدام مرطب مهدئ حسب توجيه الطبيب.","تجنب المكياج والمنتجات النشطة (فيتامين C، ريتينول) لعدة أيام."],"contra":["الحمل والرضاعة.","وجود جروح مفتوحة أو عدوى جلدية نشطة (مثل الهربس النشط).","التعرض الحديث للشمس أو حروق شمسية.","استخدام أدوية حب شباب فموية قوية مؤخرًا (تُقيَّم من الطبيب)."]}'::jsonb, 4);
insert into public.kb_articles (slug, kind, title, body, sort) values ('def:pllaexo', 'definition', 'PLLA + إكسوسومات', '{"title":"PLLA + إكسوسومات","priceNote":"الأسعار تبدأ من ١٥٠٠ جنيه، وعلى حسب الدكتور والكشف بيحدد التكلفة النهائية.","explain":"بروتوكول متقدم: الـ PLLA بيحفّز الجلد على إنتاج الكولاجين الطبيعي، والإكسوسومات بتدعم تجديد خلايا الجلد وتحسّن جودته. بيساعد في كثافة ومرونة البشرة وعلامات الشيخوخة المبكرة، والدكتور بيحدد إذا كان مناسب لحضرتك وخطة الجلسات.","neverSay":["تحديد عدد جلسات أو مدة نتيجة معينة (الدكتور بس بيحدد)","«هتبقى أصغر ١٠ سنين»"],"indications":["تحفيز إنتاج الكولاجين الطبيعي لتحسين كثافة ومرونة البشرة.","تحسين علامات الشيخوخة المبكرة وترهل الجلد الخفيف.","دعم تجديد خلايا الجلد وتحسين إشراقة البشرة."],"before":["استشارة طبية متخصصة لتحديد ملاءمة البروتوكول للحالة.","تجنب مميعات الدم والمكملات المؤثرة على التخثر حسب توجيه الطبيب.","تنظيف البشرة جيدًا والوصول بوجه خالٍ من المكياج.","إبلاغ الطبيب بأي حساسية أو ردود فعل تجاه بروتوكولات مماثلة سابقة."],"after":["تجنب التدليك القوي لمنطقة الحقن خلال الأيام الأولى.","استخدام واقي شمس يوميًا أثناء فترة التجديد.","تجنب الحرارة الشديدة (ساونا وشمس مباشرة) لعدة أيام.","المتابعة الدورية مع الطبيب حسب خطة الجلسات."],"contra":["الحمل والرضاعة.","اضطرابات تكوّن الندبات الجدرية (Keloid) غير المقيّمة طبيًا.","وجود عدوى أو التهاب نشط بمكان العلاج.","الحساسية المعروفة تجاه أي من مكونات البروتوكول."]}'::jsonb, 5);
insert into public.kb_articles (slug, kind, title, body, sort) values ('def:skinbooster', 'definition', 'سكين بوستر', '{"title":"سكين بوستر","explain":"حقن سطحية دقيقة بحمض هيالورونيك خفيف بترطّب البشرة من عمق وتحسّن النعومة والإشراقة، من غير ما تغيّر ملامح الوجه. ممكن تتعمل كإجراء وقائي أو مع خدمات تانية.","neverSay":["«هتبان كأنك أصغر»","«ملوش مضاعفات»"],"indications":["ترطيب عميق ومكثف للبشرة الجافة أو المتعبة.","تحسين نعومة وإشراقة الجلد بشكل عام.","دعم مرونة البشرة كإجراء وقائي أو تكميلي مع خدمات أخرى."],"before":["الوصول ببشرة نظيفة خالية من المكياج والزيوت.","إبلاغ الطبيب بأي حساسية تجاه حمض الهيالورونيك.","التوقف عن مميعات الدم حسب توجيه الطبيب لتقليل فرص الكدمات.","تأجيل الجلسة عند وجود التهاب أو عدوى نشطة بالوجه."],"after":["تجنب التدليك القوي لمناطق الحقن أول ٢٤ ساعة.","استخدام مرطب وواقي شمس يوميًا.","تجنب الحرارة الشديدة والتعرض المباشر للشمس لبضعة أيام.","توقّع نقاط حقن صغيرة أو احمرار بسيط يزول خلال يوم-يومين، مع إبلاغ الطبيب عند استمراره."],"contra":["الحمل والرضاعة.","وجود عدوى جلدية نشطة بمكان العلاج.","الحساسية المعروفة تجاه حمض الهيالورونيك."]}'::jsonb, 6);
insert into public.kb_articles (slug, kind, title, body, sort) values ('manual:golden_rules', 'manual', 'GOLDEN_RULES', '["الأمان قبل البيع. أي شك طبي = الدكتور هو اللي يقرر، مش اجتهادك ولا اجتهاد العميل.","ما تعدش بنتيجة. كل جلد مختلف. اللي بنوعد بيه هو تقييم دكتور مختص وشرح صريح للمتوقع.","اسمع الأول، اتكلم بعدين. نص المشاكل بتحصل لأن الأيجنت رد على سؤال العميل ما قالوش.","كل مكالمة تخلص بخطوة واضحة (Next Step). ميعاد متأكد، أو رد متفق عليه بميعاد، أو تحويل اتنفذ. مفيش «هنشوف» و«إن شاء الله» من غير تفاصيل.","اللي ما اتكتبش ما حصلش. وثق كل مكالمة فورًا في سيستم الحجز (Dentolize) بمعلومات كاملة وبلغة واضحة."]'::jsonb, 0);
insert into public.kb_articles (slug, kind, title, body, sort) values ('manual:medical_boundary', 'manual', 'MEDICAL_BOUNDARY', '[{"topic":"هل الإجراء مناسب ليّا؟","can":"«الدكتور بيقيّم كل حالة في الاستشارة ويحدد المناسب لحضرتك.»","never":"«أيوه ينفع» / «لأ مينفعش» / «ده مناسب لبشرتك»"},{"topic":"النتيجة","can":"«النتيجة بتختلف من شخص لشخص، والدكتور بيوضحلك المتوقع لحالتك.»","never":"«مضمونة» / «هتروح نهائي» / «١٠٠٪» / «هتبقى زي الصور»"},{"topic":"الألم","can":"«الإحساس بيختلف من شخص لشخص، والدكتور بيشرح كل حاجة قبل ما يبدأ.»","never":"«مش هتحس بحاجة خالص» / «بيوجع جداً»"},{"topic":"الحمل / الأدوية / الحساسية / أمراض مزمنة","can":"«دي من النقط اللي الدكتور بيقيّمها بدقة، ومهم جداً حضرتك تبلّغه بيها.»","never":"«تقدر تعمل» / «وقّف الدوا» / «كمّل الدوا» / «ده مش هيأثر»"},{"topic":"أعراض بعد جلسة","can":"اتبع بروتوكول المضاعفات (سيناريو ٥-١٠) فورًا.","never":"«ده طبيعي» / «متقلقش» / «استنى كام يوم وشوف»"},{"topic":"التشخيص","can":"«الدكتور بس هو اللي بيشخّص بعد الفحص.»","never":"«دي شكلها حساسية / فطريات / التهاب»"},{"topic":"أدوية وكريمات","can":"«أنصح حضرتك تسأل الدكتور.»","never":"أي اسم دوا أو كريم أو مكمل"},{"topic":"تعليمات قبل وبعد الجلسة","can":"تقدر تقول التعليمات المعتمدة المكتوبة زي ما هي.","never":"تعديلها أو الاجتهاد فيها أو تفصيلها لحالة العميل"},{"topic":"الأسعار والعروض","can":"الأسعار والعروض من القائمة المعتمدة بس.","never":"أرقام من عندك أو خصم من دماغك"},{"topic":"مراكز تانية","can":"«معنديش معلومات عن المراكز التانية.»","never":"أي تعليق سلبي أو مقارنة"}]'::jsonb, 1);
insert into public.kb_articles (slug, kind, title, body, sort) values ('manual:privacy_rules', 'manual', 'PRIVACY_RULES', '["قبل أي معلومة عن حجز أو ملف: تحقق من الهوية (الاسم + رقم الموبايل المسجل، ولو لزم تاريخ آخر زيارة).","ما تأكدش ولا تنفي إن شخص معين عميل عندنا لأي حد غير صاحب الحجز.","ما تبعتش تفاصيل طبية على واتساب لرقم ما اتحققتش منه.","ما تتكلمش عن حالة عميل قدام زميل مالوش علاقة أو في مكان عام، ولا تصور شاشة السيستم.","أي واقعة تسريب أو شك فيها بتحط نفسك تحت المسائلة القانونية."]'::jsonb, 2);
insert into public.kb_articles (slug, kind, title, body, sort) values ('manual:voice_table', 'manual', 'VOICE_TABLE', '[{"state":"قلقان أو متوتر","tone":"أبطأ وأدفى، جمل قصيرة مطمّنة","example":"«خد وقتك يا أستاذ/ة [الاسم]، أنا معاك خطوة بخطوة.»"},{"state":"غضبان","tone":"أهدى وأخفض (مش أعلى)","example":"«معاك حق تتضايق، وأنا هنا علشان نشوف الموضوع سوا.»"},{"state":"مستعجل","tone":"أسرع وأقصر ومباشر","example":"«تمام، هاخد ٣ بيانات بس وأخلّصلك الحجز.»"},{"state":"كبير في السن أو مش فاهم","tone":"أبطأ وأوضح، وتكرار لطيف","example":"«هعيد على حضرتك الميعاد تاني علشان نتأكد سوا.»"},{"state":"متردد","tone":"هادي وغير ضاغط","example":"«مفيش أي التزام، ده مجرد استشارة.»"}]'::jsonb, 3);
insert into public.kb_articles (slug, kind, title, body, sort) values ('manual:empathy_table', 'manual', 'EMPATHY_TABLE', '[{"situation":"قلق أو خوف","phrases":["«فاهم إن الموضوع مقلق لحضرتك.»","«سؤال حضرتك في محله جداً.»","«خلّينا نمشي خطوة خطوة.»"]},{"situation":"إحراج من مشكلة جلدية","phrases":["«ولا يهمك خالص، وخصوصية حضرتك عندنا مضمونة.»","«الدكتور بيتعامل مع حالات كتير زي دي بمنتهى الاحترافية.»"]},{"situation":"غضب","phrases":["«معاك حق تتضايق.»","«بعتذر لحضرتك إن التجربة كانت كده.»","«هتابع الموضوع بنفسي لحد ما نوصل لحل.»"]},{"situation":"انتظار طويل","phrases":["«شكراً لصبر حضرتك.»","«بعتذر عن التأخير.»"]},{"situation":"خيبة أمل","phrases":["«فاهم إن ده مش اللي كنت متوقعه.»","«خلّيني أشوف إزاي أقدر أساعد حضرتك.»"]},{"situation":"امتنان","phrases":["«شكراً إن حضرتك بلّغتنا.»","«ده يساعدنا نخدم حضرتك أحسن.»"]}]'::jsonb, 4);
insert into public.kb_articles (slug, kind, title, body, sort) values ('manual:replace_table', 'manual', 'REPLACE_TABLE', '[{"instead":"«مش عارف»","say":"«هتأكدلك حالاً.» / «خلّيني أراجع وأرجعلك بمعلومة دقيقة.»"},{"instead":"«ده مش شغلي» / «مش من اختصاصي»","say":"«هوصّلك للشخص المختص وهتابع معاك.»"},{"instead":"«مينفعش»","say":"«اللي أقدر أعمله دلوقتي هو...»"},{"instead":"«ماعندناش»","say":"«المتاح دلوقتي هو...»"},{"instead":"«استنى»","say":"«ثواني أراجع لحضرتك.»"},{"instead":"«حضرتك مفهمتش» / «حضرتك غلطان»","say":"«يمكن أنا ما وضّحتش كويس، خليني أشرحلك تاني.»"},{"instead":"«دي سياسة الشركة»","say":"«الإجراء المعتمد عندنا علشان سلامة حضرتك هو...»"},{"instead":"«معلش»","say":"«بعتذر لحضرتك عن...»"},{"instead":"«حاضر حاضر» (وإنت مش هتنفذ)","say":"ما تعدش غير بالحاجة اللي هتنفذها فعلاً وبميعاد محدد."}]'::jsonb, 5);
insert into public.kb_articles (slug, kind, title, body, sort) values ('manual:call_steps', 'manual', 'CALL_STEPS', '[{"n":"١","name":"الترحيب","goal":"انطباع أول دافي ومحترف","phrase":"«ألور كلينكس، صباح الخير، [اسمك] مع حضرتك.»"},{"n":"٢","name":"التعريف","goal":"تعرف مين بيتكلم وأول مرة ولا لأ","phrase":"«أهلاً أستاذ/ة [الاسم]، أقدر أساعد حضرتك إزاي؟»"},{"n":"٣","name":"الاستكشاف / الفهم","goal":"تفهم الطلب الحقيقي","phrase":"«يعني حضرتك... مظبوط؟»"},{"n":"٤","name":"المعلومة أو الحل","goal":"تجاوب بوضوح وأمان","phrase":"«الإجابة كذا، وده علشان كذا.»"},{"n":"٥","name":"الإجراء","goal":"تحجز أو تسجل أو تحوّل","phrase":"«هحجزلك دلوقتي، ممكن أتأكد من البيانات؟»"},{"n":"٦","name":"الخلاصة","goal":"تكرر الاتفاق والخطوة الجاية","phrase":"«تمام كده اتفقنا ع الميعاد...»"},{"n":"٧","name":"الإغلاق","goal":"ختام دافي + توثيق","phrase":"«أي استفسار آخر؟ شكراً لاختيارك ألور.»"}]'::jsonb, 6);
insert into public.kb_articles (slug, kind, title, body, sort) values ('manual:scenarios', 'manual', 'SCENARIOS', '[{"id":"٥-١","title":"استفسار عام: «عندكم إيه؟»","goal":"تفهم اللي محتاجه فعلاً، وتشرح الخدمة المناسبة بجملتين، وتحجزله استشارة.","steps":["اسأل سؤال مفتوح: إيه اللي عايز يعمله؟","اسمع وأعد الصياغة.","اشرح الخدمة المناسبة بجملتين من غير وعود.","وضّح إن الدكتور هو اللي بيحدد المناسب.","اعرض حجز استشارة."],"script":"العميل: عندكم إيه للبشرة؟\nأنت: أهلاً بحضرتك. عندنا خدمات كتير للبشرة. علشان أرشحلك الأنسب، ممكن أعرف حضرتك بتدور على إيه بالظبط؟ خطوط تعبير، ترطيب ونضارة، آثار حبوب، ولا حاجة تانية؟","forbidden":["ما تسردش قائمة الخدمات كلها في نفس واحد.","ما توصّيش بخدمة من غير ما تفهم المشكلة."]},{"id":"٥-٢","title":"حجز موعد جديد","goal":"تحجز بدقة (بيانات صح، فرع صح، وقت مؤكد) وتخلّي العميل عارف بالظبط هيعمل إيه.","steps":["تحقق في Dentolize إن العميل مش مسجل قبل كده.","اسأل: الاسم، الرقم، الفرع، الخدمة (أو استشارة).","اعرض ميعادين مناسبين.","اسأل السؤال العام الواحد للدكتور (أي حاجة صحية حابب يبلّغ بيها؟).","كرر البيانات بالكامل وأكدها.","اذكر تعليمات ما قبل الجلسة المعتمدة للخدمة.","طمّنه على الموافقة المسبقة، وابعت رسالة تأكيد."],"script":"أنت: يشرفني أساعد حضرتك في الحجز. ممكن الاسم ثنائي لو سمحت؟ ... ورقم موبايل حضرتك؟ (يكرره) ... حضرتك هتزورينا في أنهي فرع؟ ... عندنا الثلاثاء ٥ العصر أو الأربعاء ١٢ الظهر، أنهي أنسب؟ ... وفي أي حاجة صحية حابب حضرتك تبلّغها للدكتور قبل الميعاد؟","tip":"لو العميل ذكر (حمل، حرق شمس، عدوى، أدوية) أثناء الحجز → سجّلها في ملاحظة الحجز وبلّغ الفرع، لأن الدكتور ممكن يقرر التأجيل.","forbidden":["ما تأكدش خدمة أو مدة جلسة من دماغك.","ما تحجزش من غير ما تكرر الرقم والميعاد."]},{"id":"٥-٣","title":"اختيار الفرع","goal":"توصله لأقرب فرع مناسب وتديه العنوان بوضوح.","steps":["اسأل: «حضرتك في أنهي محافظة أو منطقة؟»","اقترح الأقرب. لو في طنطا وضّح الفرقين (الاستاد وسعيد).","اعرض العنوان بوضوح وابعته رسالة.","تأكد إن الخدمة متوفرة في الفرع."],"script":"أنت: عندنا ٦ فروع: التجمع الخامس، المنصورة، طنطا (فرعين: الاستاد وسعيد)، كفر الشيخ، وشبين الكوم. حضرتك ساكن في أنهي محافظة علشان أرشحلك الأقرب؟"},{"id":"٥-٤","title":"تعديل أو إلغاء أو تأخير ميعاد","goal":"تنفذ الطلب بسلاسة، وتحاول تحافظ على الحجز بلطف من غير ضغط، وتوثّق.","steps":["تحقق من الهوية وادخل على الحجز في Dentolize.","اسأل السبب بلطف (اختياري).","اعرض ميعاد بديل قبل الإلغاء.","نفّذ التعديل أو الإلغاء وأكد بالتفاصيل.","ابعت رسالة تأكيد."],"script":"تأجيل — العميل: مش هقدر أجي بكرة.\nأنت: ولا يهمك يا أستاذ/ة [الاسم]. تحب أنقلك لميعاد تاني؟ عندنا [اختيار ١] أو [اختيار ٢].\n\nإلغاء — أنت: تمام، لو متاح حضرتك توضحيلي سبب إلغاء الحجز؟ إسألي عن إمكانية التأجيل، ولو حابب تحجز في أي وقت تاني تقدر تشرفنا بالإتصال.\n\nعميل هيتأخر — أنت: شكراً إنك بلغتنا. هبلغ الفرع حالاً. تقريباً هتوصل بعد قد إيه؟","forbidden":["ما تحاسبش العميل ولا تلوّمه («ده أنا حاجزلك بالعافية»)."],"escalation":"لو العميل ذكر حرق شمس أو عدوى أو حمل قبل جلسة: ما تلغيش ولا تأكد، سجل ملاحظة وبلغ الفرع ليقرر الدكتور."},{"id":"٥-٥","title":"الاستفسار عن الأسعار وخصم «غالي»","goal":"تدي سعر واضح من القائمة المعتمدة من غير هروب، وتربطه بقيمة الاستشارة.","steps":["حدد الخدمة (السعر بيختلف: المنطقة، الكمية، الحالة).","قول السعر من القائمة المعتمدة (أو «بيبدأ من»).","وضّح إن التقييم الطبي هو اللي بيحدد السعر النهائي.","اعرض الاستشارة."],"script":"العميل: بكام الفيلر؟\nأنت: سؤال مهم ومن حقك تعرفه. سعر الفيلر يبدأ من [..] ويتحدد حسب المنطقة والكمية اللي الدكتور يقيّمها لحالة حضرتك في الاستشارة. تحب أحجزلك استشارة يوضحلك فيها كل حاجة؟\n\nاعتراض «غالي» — أنت: فاهم إن السعر عامل مهم لحضرتك. اللي بيخلّي الخدمة عندنا مختلفة إنها بإشراف طبي متخصص وبروتوكولات تعقيم ومكافحة عدوى صارمة. تحب أشوفلك لو في عرض متاح حاليًا؟","forbidden":["ما تقولش رقم من دماغك أو «تقريباً كذا».","ما تدّيش خصم أو عرض خارج القائمة.","ما تقارنش بأسعار مراكز تانية ولا تقلل منها."],"escalation":"أي طلب خصم خارج العروض المعتمدة إسأل مديرك."},{"id":"٥-٦","title":"«أنا ينفع أعمل الإجراء ده؟» (ملاءمة طبية)","goal":"تطمّنه من غير ما تدّي رأي طبي، وتجمّع المعلومة العامة، وتوصله للدكتور.","steps":["اعترف بالسؤال: «سؤال مهم جداً.»","وضح إن التقييم الطبي للدكتور.","اسأل سؤال واحد: «إيه الخدمة اللي عايزها؟»","احجز استشارة أو رتّب مكالمة من الدكتور/التمريض.","سجل النقطة في ملاحظة الحجز."],"script":"حمل أو رضاعة — العميل: أنا حامل، ينفع أعمل بوتوكس؟\nأنت: شكراً إن حضرتك قلتيلي، ده مهم جداً. الحمل والرضاعة من الحالات اللي الدكتور بيقيّمها بدقة، فمقدرش أقول ينفع ولا لأ. هحجزلك استشارة، وهسجّل الملاحظة دي علشان الدكتور يبقى عارف من الأول.","forbidden":["«ينفع» أو «مينفعش» أبداً، حتى لو الحالة شكلها بسيطة.","تنصح بإيقاف أو بدء أي دوا أو مكمل.","تدّي أمثلة («واحدة صاحبتي عملتها وهي حامل»)."],"escalation":"لو العميل عنده أعراض حاليًا (ألم، تورم، تغيّر لون) → سيناريو ٥-١٠ فورًا."},{"id":"٥-٧","title":"«هتدي نتيجة؟ هتروح نهائي؟»","goal":"تكون صادق، من غير تحطيم حماسه ولا وعد كاذب.","script":"العميل: هيروح الشعر نهائي؟ وكام جلسة؟\nأنت: فاهم إن حضرتك عايز تتطمن على النتيجة، وده حقك تمامًا. النتيجة بتختلف من شخص لشخص، وعدد الجلسات بيحدده الدكتور بعد التقييم. اللي أقدر أوعد بيه إن الدكتور هيقيّم حالة حضرتك ويوضحلك المتوقع بصراحة.","forbidden":["«نهائي» / «مضمون» / «١٠٠٪» / «هتبقى زي الصورة».","تحدد عدد جلسات أو مدة نتيجة."]},{"id":"٥-٨","title":"«بيوجّع؟ وهبقى إزاي بعده؟»","goal":"تطمّنه بصدق، وتنقل له التعليمات المعتمدة اللي ممكن تتقال بأمان.","script":"العميل: أنا بخاف من الحقن، بيوجع؟\nأنت: فاهم إن الموضوع مقلق، وسؤال حضرتك في محله. الإحساس بيختلف من شخص لشخص، والدكتور بيشرح لحضرتك كل حاجة قبل ما يبدأ.","forbidden":["«مش هتحس بحاجة» / «بيوجع جامد» / «تقدر ترجع شغلك على طول» (ده حكم طبي)."]},{"id":"٥-٩","title":"سؤال عن التعليمات بعد الجلسة (عميل قديم)","goal":"تنقل التعليمات المعتمدة زي ما هي، وتتأكد إنه فاهم.","steps":["تحقق من الهوية وحدد أنهي خدمة وإمتى.","اقرا التعليمات المعتمدة بالحرف، من غير تفصيل شخصي.","Teach-back: اطلب منه يكرر أهم نقطتين.","اسأل مباشر: «حضرتك ملاحظ أي حاجة غير مريحة دلوقتي؟»","لو قال أي عرض ← سيناريو ٥-١٠. لو لأ ← وثّق."],"script":"العميل: أنا عملت ليزر امبارح، ينفع أروح البحر؟\nأنت: التعليمات المعتمدة بعد الليزر إن حضرتك تتجنب الشمس المباشرة وتستخدم واقي شمس عالي لمدة أسبوعين، وتتجنب الحمامات الساخنة جدًا والساونا ٢٤-٤٨ ساعة. ممكن تكررلي أهم نقطتين علشان أتأكد إني وضّحت؟","forbidden":["تجاوب على أسئلة زي «أقدر أحط كريم كذا؟» بحكم شخصي، إلا لو في تعليمات مباشرة.","تقول «ده طبيعي» لأي حاجة بيوصفها."]},{"id":"٥-١٠","title":"أعراض أو مضاعفات بعد جلسة (أخطر سيناريو)","goal":"تتصرف بهدوء وسرعة، ما تشخّصش، ما تطمّنش كذب، وتوصّل المعلومة للدكتور فورًا.","danger":"علامات الطوارئ الفورية (Red Flags): صعوبة في التنفس — تورم في الوجه أو الشفايف أو اللسان — دوخة شديدة أو إغماء — ألم شديد ومفاجئ — شحوب شديد أو تغيّر في لون الجلد بعد الفيلر.\n\nأنت: أستاذ/ة [الاسم]، اللي حضرتك بتوصفه محتاج تدخل طبي فوري. من فضلك اتصل بالإسعاف على ١٢٣ أو روح أقرب طوارئ حالاً. أنا هبلّغ الدكتور المعالج والمدير الطبي دلوقتي. حضرتك معاك حد دلوقتي؟\n\nبلغ مديرك فورًا.","steps":["لو مفيش Red Flag: اهدى وطمّنه إنك سمعته.","اجمع ٥ معلومات بس: الاسم والرقم — الفرع — الخدمة — وقت الجلسة ومين الدكتور — الأعراض بكلام العميل نفسه ومن إمتى.","بلغ الدكتور أو مدير الفرع فورًا (مش آخر اليوم).","اتفق مع العميل على خطوة واضحة: مين هيتصل بيه وخلال قد إيه.","وثق كلام العميل بالكامل، وتأكد إن المدير الطبي اتبلغ في نفس اليوم.","تابع: اتأكد إن الدكتور فعلاً تواصل مع العميل."],"script":"سكريبت الأعراض بدون Red Flag — أنت: فاهم إن ده مقلق، وشكراً لحضرتك إنك بلغتنا فورًا. أنا هبلغ الدكتور حالاً، وهيتواصل مع حضرتك خلال [X] دقيقة على نفس الرقم. ولو الأعراض زادت قبل ما نتصل، كلمنا فورًا أو روح أقرب طوارئ.","forbidden":["«ده طبيعي» / «متقلقش» / «استنى كام يوم وشوف».","تنصح بدوا أو كريم أو مضاد حيوي أو أي حاجة.","تشخص السبب أو تناقش مسؤولية.","تعد بتعويض أو استرداد.","تقفل المكالمة قبل ما التصعيد يتم."],"escalation":"الإسعاف ١٢٣ (للعميل) + الدكتور المعالج/المناوب + المدير الطبي + مديرك — فورًا، قبل أي حاجة تانية."},{"id":"٥-١١","title":"الشكوى (إطار HEAR)","goal":"لازم العميل يحس إنه اتسمع واتحل موضوعه أو جاري العمل على حله.","steps":["H — Hear: اسمع من غير مقاطعة، واكتب.","E — Empathize: اعترف بإحساسه.","A — Apologize: اعتذر عن التجربة مش عن اعتراف بخطأ طبي.","R — Resolve: اعرض حل أو خطوة واضحة بميعاد، أو صعد للمسؤول.","سجّل الشكوى: الاسم، الرقم، الفرع، تاريخ الواقعة، وصف بكلام العميل، المطلوب."],"script":"العميل: استنيت في الفرع ساعة كاملة وماحدش اعتذر لي!\nأنت: معاك حق تتضايق، وأنا بعتذر لحضرتك جدًا على التجربة دي. علشان أتابع الموضوع صح، ممكن أعرف يوم إيه وفي أنهي فرع؟ أنا هسجّل الشكوى حالاً وأرفعها لمدير الفرع، وهيتواصل مع حضرتك خلال [المدة المعتمدة].","forbidden":["تدافع أو تبرر («الفرع كان زحمة»).","تلوم زميل أو فرع.","تعد بحاجة مش في إيدك (تعويض، فصل موظف).","تقول «هعرف الإدارة» من غير ما تسجل فعلاً."],"escalation":"أي شكوى فيها مضاعفات طبية، أو تهديد قانوني/إعلامي، أو تصوير → Team Leader ومدير الفرع فورًا."},{"id":"٥-١٢","title":"العميل الغضبان أو اللي بيزعق","goal":"تهدّي الموقف من غير ما تتخلى عن دورك، وتوصل لحل أو تصعيد منظم.","steps":["سيبه يفرّغ ٦٠-٩٠ ثانية من غير مقاطعة.","وقفة + نفس + نبرة أهدى.","اسمه + اعتراف: «معاك حق تتضايق يا أستاذ/ة [الاسم].»","ركّز على الحل: «خلّيني أفهم بالظبط اللي حصل.»","اعرض خيار وخطوة بميعاد.","لو استمر الغضب ورفض الحل → اعرض التحويل للمدير."],"script":"العميل: أنتوا ناس مش محترمين! أنا حجزت من أسبوع وتقولولي مفيش حجز!\nأنت: أستاذ/ة [الاسم]، معاك حق تتضايق جدًا، وأنا بعتذر لحضرتك. خلّيني أشوف الموضوع فورًا.\n\nلو طلب المسؤول — أنت: طبعًا، من حقك تمامًا. هاقدم لحضرتك طلب دلوقتي، وهبلغه بالتفاصيل علشان حضرتك ما تعيدش الكلام.","forbidden":["ما ترفضش تحويل العميل للمسؤول أبدًا.","ما ترد بنفس النبرة أو تقول «حضرتك بتزعق».","ما تسكتش بعد ما يخلص، بل رد بجملة تعاطف."]},{"id":"٥-١٣","title":"العميل المتردد","goal":"تفهم سبب التردد الحقيقي، وتقلل الخوف من الالتزام، من غير أي ضغط.","steps":["اسأل: «إيه النقطة اللي لسه شاغلة حضرتك؟»","حدد السبب: سعر؟ خوف؟ توقيت؟ رأي حد؟","عالج السبب بمعلومة صادقة.","قلل الالتزام: «الاستشارة مش معناها إنك لازم تعمل الإجراء.»","استأذنه في متابعة لطيفة."],"script":"العميل: هفكر وأرجعلك.\nأنت: طبعًا، القرار قرار حضرتك. علشان أساعدك تفكر صح، ممكن أعرف النقطة اللي لسه محتاجة توضيح؟","forbidden":["ضغط أو عروض مزيفة («العرض بينتهي النهارده» لو مش حقيقي).","تتصل بالعميل أكتر من المتفق عليه."]},{"id":"٥-١٤","title":"المقارنة بمنافس أو برأي دكتور آخر","goal":"تحافظ على مصداقيتك من غير هجوم على حد.","script":"العميل: مركز تاني قالي إنهم أرخص وبيدوني ضمان.\nأنت: أنا مقدرش أعلق على مراكز تانية لأني ماعنديش معلومات عنها. اللي أقدر أقوله إن عيادات ألور بإشراف طبي متخصص، وبروتوكولات تعقيم ومكافحة عدوى صارمة. وأنصح حضرتك تاخد الاستشارة وتقارن بنفسك.","forbidden":["«إحنا أحسن من...» أو أي انتقاد لمركز أو دكتور.","تعد بضمان أو تسعير مقابل منافس."],"escalation":"لو العميل بيذكر تقييم سلبي عن ألور نفسها، عامله كشكوى (٥-١١)."},{"id":"٥-١٥","title":"«عايز أكلم الدكتور مباشرة»","goal":"تلبي احتياجه بطريقة منظمة من غير ما تعطل الدكتور في جلسة.","steps":["اعرف الموضوع بشكل مختصر.","لو في أعراض ← ٥-١٠ فورًا.","لو سؤال غير عاجل: رتّب مكالمة من الدكتور/التمريض أو استشارة.","إبعت التفاصيل ع الواتساب للدكتور أو مدير الفرع."],"script":"أنت: الدكتور غالبًا بيكون في جلسات مع مرضى، علشان كده مقدرش أحوّل المكالمة مباشرة، لكن أقدر أرتّب مكالمة منه أو من التمريض على رقم حضرتك، أو أحجزلك استشارة.","forbidden":["تحوّل مكالمة العميل للدكتور وهو في جلسة من غير تنسيق.","تجاوب بدل الدكتور علشان «تخلص الموضوع»."]},{"id":"٥-١٦","title":"حد غير العميل بيسأل عن ميعاد أو بيانات","goal":"حماية خصوصية العميل من غير ما تكون جاف.","script":"العميل: هي عندكم ميعاد إمتى؟ أنا أختها.\nأنت: أهلاً بحضرتك. حفاظًا على خصوصية عملائنا، مقدرش أؤكد أو أفصح عن أي بيانات إلا لصاحب الحجز نفسه. لو متاح ممكن هي تكلمنا مباشرة.","forbidden":["ما تأكدش ولا تنفي إن الشخص عميل.","ما تفصحش عن الخدمة أو الميعاد حتى لو الطرف بيبكي أو بيلحّ."],"escalation":"لو في تفويض مكتوب من العميل أو حالة استثنائية، بلغ مديرك فورًا وهو يقرر."},{"id":"٥-١٧","title":"العميل كتير الكلام","goal":"تحترمه وتوجه المكالمة من غير ما تقاطعه بشكل ملحوظ.","steps":["اسمع دقيقة، وبعدين قاطعه بلطف باسمه.","لخّص أهم نقطة وارجع للمطلوب.","استخدم أسئلة مغلقة تضيق المكالمة."],"script":"أنت: معلش أقاطع حضرتك لحظة يا أستاذ/ة [الاسم] علشان أستفيد من وقتك وأخدم طلبك صح. اللي فهمته إن أهم حاجة عند حضرتك هي [..]. تحب أحجزلك استشارة دلوقتي؟","forbidden":["تنهي المكالمة فجأة أو تظهر إنك مش مهتم.","تتنهد أو تقول «اختصر يا فندم»."]},{"id":"٥-١٨","title":"العميل المتوتر لأول مرة / كبير السن / مش فاهم","goal":"تحسسه بالأمان وتتأكد إنه فهم فعلاً.","steps":["تكلم أبطأ وأوضح، وقسّم المعلومة لأجزاء صغيرة.","كرر النقط المهمة (الميعاد، العنوان) بلطف.","اطلب منه يكرر (Teach-back).","اقترح تبعت التفاصيل على رسالة، أو لفرد من العيلة بإذنه."],"script":"أنت: ولا يهمك يا أستاذ/ة [الاسم]، خد وقتك وأنا معاك خطوة خطوة. الدكتور هيشرحلك كل حاجة قبل أي إجراء، ومفيش أي حاجة بتتعمل من غير موافقة حضرتك.","forbidden":["تستعجله أو تتنهد.","تقول «كنت قلتلك» أو «مش فاهم ليه؟»"]},{"id":"٥-١٩","title":"مواضيع حساسة: مناطق خاصة، جنس مقدم الخدمة، الرجال","goal":"تتعامل باحترام كامل، من غير تعليق ولا فضول ولا إحراج.","script":"العميل: أنا محرجة شوية... عايزة أسأل عن ليزر في منطقة حساسة.\nأنت: ولا يهمك خالص يا أستاذة [الاسم]، خصوصية حضرتك عندنا مضمونة، والفريق بيتعامل مع كل الحالات بمنتهى الاحترافية. تحبي أسجل طلب إن الجلسة تكون مع [دكتورة/فنية]؟","forbidden":["تعلّق أو تضحك أو تسأل عن تفاصيل شخصية.","تعد بمقدم خدمة معين قبل تأكيد الفرع.","تفرّق في التعامل بين رجالة وستات — المعايير واحدة."]},{"id":"٥-٢٠","title":"طلب خصم أو عرض","goal":"تكون صادق، وتقول العروض الفعلية بس، وتصعّد الطلبات الخاصة.","script":"العميل: ممكن تدّيني خصم؟\nأنت: العروض المتاحة حاليًا هي [العروض الموجودة حاليًا]. لو حضرتك حابب نحجز...","forbidden":["تعد بخصم من عندك أو «هدبّرلك».","تخترع عرض لإرضاء العميل.","تقارن أسعار الفروع لو مش مؤكد."],"escalation":"طلب خصم خارج العروض → Team Leader."},{"id":"٥-٢١","title":"مش عارف الإجابة / السيستم واقع","goal":"ما تخترعش ولا تخسر ثقة العميل.","script":"مش عارف — أنت: أنا آسف جدًا، عندنا مشكلة بسيطة في السيستم هتتحل في أقرب وقت، وعايز أدي حضرتك معلومة دقيقة. خليني أتأكد الأول.\n\nالسيستم واقع — أنت: السيستم عندنا بيعمل تحديث دلوقتي. مش هيأثر على حجز حضرتك: هسجّل طلب الحجز يدويًا وأأكده معاك خلال [المدة].","tip":"إجراء تعطل السيستم: نسجل في شيت إكسيل بنفس البيانات، وأدخله في السيستم أول ما يرجع.","forbidden":["تخمن معلومة أو تقول «على حسب علمي» في حاجة طبية أو مالية."]},{"id":"٥-٢٢","title":"استرداد أموال أو مشكلة في الدفع","goal":"تسجل الموضوع بدقة وتوصله للمسؤول الصح من غير وعد بحاجة مش في إيدك.","steps":["اسمع واعتذر عن الموقف.","اجمع: الاسم، الرقم، الفرع، التاريخ، الخدمة، المبلغ، المشكلة.","وضّح إن الموضوع هيتراجع من الحسابات/مدير الفرع وحدد ميعاد رد.","سجّل وصعّد."],"script":"أنت: بعتذر لحضرتك على المشكلة دي. علشان أراجعها صح، ممكن الاسم والرقم والفرع وتاريخ الدفع والمبلغ؟ أنا هسجّل الموضوع وأرفعه للمسؤول، وهيتواصل مع حضرتك خلال [المدة المعتمدة].","forbidden":["«هترجعلك فلوسك» أو «مفيش استرداد» قبل قرار المسؤول.","تناقش تفاصيل مالية داخلية."],"escalation":"كل طلبات الاسترداد والتعويض والفواتير → Team Leader ثم المسؤول المالي."},{"id":"٥-٢٣","title":"شكوى من النتيجة («معملتش حاجة» / «مش زي ما توقعت»)","goal":"تسمعه بصدق، وتفتح له باب المتابعة الطبية، من غير جدال ولا اعتراف ولا وعد.","steps":["اسمع بالكامل واعترف بإحساسه.","اسأل: أنهي خدمة، إمتى، أنهي فرع، مين الدكتور.","ما تفسّرش سبب طبي ولا تقارن بنتائج تانية.","اعرض ميعاد متابعة مع الدكتور.","وثّق بكلام العميل نفسه، وبلغ مديرك والمدير الطبي."],"script":"العميل: عملت الجلسة من شهر ومفيش أي فرق!\nأنت: فاهم إن ده مش اللي كنت متوقعه، وبعتذر لحضرتك إن التجربة كانت كده. أهم حاجة إن الدكتور يشوف حالتك بنفسه ويقيم الموضوع. ممكن أعرف أنهي جلسة عملتها وإمتى وفي أنهي فرع؟","forbidden":["تجادل («ده لسه بدري») — ده حكم طبي.","تعد بإعادة أو تعويض.","تقلل من إحساسه أو تقول «ده مش من عندنا»."],"escalation":"تصعيد كل شكوى نتيجة لمديرك والمدير الطبي، مع تسجيل في السيستم."},{"id":"٥-٢٤","title":"العميل المسيء (شتائم أو تهديد)","goal":"حماية نفسك وتحافظ على الاحترام، وتنهي المكالمة بشكل منظم لو لزم.","steps":["الإنذار الأول: اطلب الاحترام بهدوء وأكد إنك عايز تساعده.","الإنذار الثاني: وضح إنك هتضطر تنهي المكالمة.","الإنهاء: لو استمر، أنه المكالمة بأدب.","بعدها: وثّق الواقعة وبلغ مديرك فورًا."],"script":"الإنذار الأول — أنت: أستاذ/ة [الاسم]، أنا مقدّر إن حضرتك متضايق وفعلًا عايز أساعد حضرتك، بس أسف محتاجين نكمل المكالمة بدون استخدام ألفاظ خارجة.\n\nالإنذار الثاني — أنت: بعد إذنك، لو استمر استخدام الألفاظ الخارجة هضطر أنهي المكالمة.\n\nالإنهاء — أنت: أنا آسف إني مش هقدر أكمل المكالمة. شكرًا لحضرتك.","forbidden":["ما ترد بنفس الأسلوب ولا تشتم ولا تسخر.","ما تنهيش المكالمة قبل الإنذارين (إلا لو فيه تهديد بالعنف)."],"escalation":"تهديد بالعنف أو بأذى: بلغ مديرك فورًا وقبل أي حاجة تانية."}]'::jsonb, 7);
insert into public.kb_articles (slug, kind, title, body, sort) values ('manual:objections', 'manual', 'OBJECTIONS', '[{"objection":"«غالي»","reason":"ميزانية أو مش شايف القيمة","response":"فاهم إن السعر مهم لحضرتك. الاستشارة من غير التزام، والدكتور بيوضحلك الخيارات المناسبة. تحب أشوفلك لو في عرض متاح؟"},{"objection":"«هفكر»","reason":"خوف أو معلومة ناقصة","response":"طبعًا. إيه النقطة اللي لسه محتاجة توضيح علشان أساعدك؟"},{"objection":"«بخاف من الحقن»","reason":"قلق من الألم","response":"فاهم جدًا. الدكتور بيشرحلك كل حاجة قبل ما يبدأ، وتقدر تسأل في أي لحظة، ومفيش حاجة بتتعمل من غير موافقة حضرتك."},{"objection":"«سمعت إن ناس اتبوظ وشها»","reason":"خوف من المضاعفات","response":"فاهم قلق حضرتك، وسلامتك أهم حاجة. علشان كده أي خدمة عندنا بتبدأ باستشارة وتقييم دكتور، وبمعايير تعقيم ومكافحة عدوى صارمة."},{"objection":"«الفرع بعيد»","reason":"مشوار أو ظروف","response":"فاهم. عندنا ٦ فروع، تحب أشوفلك الأقرب لحضرتك؟"},{"objection":"«مفيش وقت»","reason":"جدول مزدحم","response":"أقدر أعرض عليك أكتر من ميعاد، تختار الأنسب لجدولك."},{"objection":"«هسأل جوزي/أهلي الأول»","reason":"قرار مشترك","response":"طبعًا، قرار مهم. تحب أبعتلك التفاصيل على واتساب تعرضها عليهم، وأتواصل مع حضرتك بعد يومين؟"},{"objection":"«مركز تاني أرخص»","reason":"مقارنة سعر","response":"مقدرش أعلّق على مراكز تانية. وأنصح تاخد الاستشارة وتقارن بنفسك."},{"objection":"«مش واثق في النتيجة»","reason":"خوف من عدم التحقق","response":"معاك حق تتأكد. الدكتور هيوضحلك المتوقع بصراحة لحالتك، ومفيش وعود بنتيجة مضمونة."},{"objection":"«عايز جلسة واحدة بس»","reason":"ميزانية أو وقت","response":"عدد الجلسات بيحدده الدكتور حسب الحالة والخدمة، وهيوضحلك ده في الاستشارة."},{"objection":"«كلموني بعدين»","reason":"وقت مش مناسب","response":"تمام. إيه أنسب وقت أكلم فيه حضرتك؟ وسجّل الوقت والتزم بيه."}]'::jsonb, 8);
insert into public.kb_articles (slug, kind, title, body, sort) values ('manual:outbound', 'manual', 'OUTBOUND', '[{"title":"تذكير بالميعاد (قبل ٢٤ ساعة)","script":"مساء الخير، معاك [اسمك] من عيادات ألور. هل بكلم أستاذ/ة [الاسم]؟\n(لو أيوه) بتصل أفكر حضرتك بميعادك بكرة الساعة [..] في فرع [..]. هل هتقدر تيجي؟\nلو أيوه: تمام. وقبل الميعاد [أهم تعليمة معتمدة للخدمة]. ولو ظهرت أي ظروف كلمنا على [الرقم].\nلو لأ ← سيناريو ٥-٤ (تعديل الميعاد)."},{"title":"متابعة بعد الجلسة (٢٤-٤٨ ساعة)","script":"أهلاً أستاذ/ة [الاسم]، معاك [اسمك] من عيادات ألور. بتصل أتطمن على حضرتك بعد جلسة [الخدمة]. حضرتك عامل/ة إيه؟ (استمع بدون مقاطعة)\nوحضرتك ملاحظ/ة أي حاجة غير مريحة دلوقتي؟\nلو لأ: الحمد لله، أفكر حضرتك بأهم تعليمتين. ولو حصل أي حاجة كلمنا في أي وقت.\nلو في أي عرض ← سيناريو ٥-١٠ فورًا."},{"title":"استرجاع عميل لم يتم تأكيد حجزه (No-show)","script":"أهلاً أستاذ/ة مع حضرتك [الاسم]، من عيادات ألور. حاولنا الاتصال بحضرتك لتأكيد ميعادك ومعرفناش نوصلك، كنا حابين نأكد ميعاد الحجز بكرة الساعة [..] في فرع [..]."},{"title":"متابعة عميل مهتم (Lead)","script":"مساء الخير، معاك [اسمك] من عيادات ألور. حضرتك كنت سألت عن [الخدمة]. هل ده وقت مناسب أخد دقيقة من وقت حضرتك؟\nلو «مش مهتم»: تمام، شكرًا لوقت حضرتك، ولو احتجت أي حاجة إحنا موجودين."},{"title":"رسالة صوتية أو حد غير العميل رد","script":"أهلاً، معاك [اسمك] من عيادات ألور. كنت بكلم أستاذ/ة [الاسم] بخصوص موضوع خاص. ممكن يتواصل معانا على [الرقم] لتأكيد الميعاد. شكرًا."}]'::jsonb, 9);
insert into public.kb_articles (slug, kind, title, body, sort) values ('manual:outbound_rules', 'manual', 'OUTBOUND_RULES', '["عرّف نفسك وسبب المكالمة في ١٠ ثواني، واطلب إذن: «هل ده وقت مناسب لدقيقة؟»","الخصوصية أولاً: لو حد غير العميل رد، ما تذكرش الخدمة ولا تفاصيل الحجز.","احترم «مش مهتم» و«ما تتصلش تاني» وسجّلها فورًا في السيستم.","التزم بميعاد أي Callback وعدت بيه."]'::jsonb, 10);
insert into public.kb_articles (slug, kind, title, body, sort) values ('manual:escalation_matrix', 'manual', 'ESCALATION_MATRIX', '[{"situation":"علامات طوارئ (Red Flags)","who":"الإسعاف ١٢٣ (للعميل) + الدكتور المعالج/المناوب + المدير الطبي + مديرك","when":"فورًا، قبل أي حاجة تانية"},{"situation":"أعراض بعد جلسة بدون Red Flag","who":"الدكتور المناوب / مدير الفرع ثم المدير الطبي","when":"فورًا، والتوثيق وإبلاغ المدير الطبي في نفس اليوم"},{"situation":"سؤال طبي خارج المكتوب","who":"الدكتور (مكالمة مرتبة)","when":"خلال المدة المعتمدة"},{"situation":"شكوى عادية","who":"مديرك ثم مدير الفرع","when":"داخل المكالمة لو العميل طلب، أو Ticket بميعاد رد"},{"situation":"شكوى نتيجة / تهديد قانوني أو إعلامي","who":"مديرك + مدير الفرع + المدير الطبي","when":"فورًا"},{"situation":"طلب خصم خاص / استرداد / مشكلة فاتورة","who":"مديرك + مدير الفرع","when":"Ticket + ميعاد رد"},{"situation":"عميل مسيء","who":"مدير الفرع","when":"بعد المكالمة، وفورًا لو في تهديد بالعنف"},{"situation":"عطل السيستم","who":"مديرك + مدير الفرع + IT","when":"فورًا"},{"situation":"شك في تسريب بيانات","who":"مديرك + الإدارة","when":"فورًا"}]'::jsonb, 11);
insert into public.kb_articles (slug, kind, title, body, sort) values ('manual:handover_card', 'manual', 'HANDOVER_CARD', '["مين: اسم العميل ورقمه.","فين: الفرع والخدمة.","إيه اللي حصل: جملة أو جملتين بكلام العميل.","اللي اتعمل لحد دلوقتي: اللي قلته وسجلته.","المطلوب: رد؟ زيارة؟ قرار؟ وبميعاد إيه؟"]'::jsonb, 12);
insert into public.kb_articles (slug, kind, title, body, sort) values ('manual:contacts', 'manual', 'CONTACTS', '[{"role":"مديرك المباشر","name":"أحمد طاهر","phone":"01065757169"},{"role":"مدير الفروع","name":"راندا رشدي","phone":"01066662147"},{"role":"مدير فرع التجمع الخامس","name":"شاهي","phone":"01094557401"},{"role":"مدير فرع المنصورة","name":"هدير","phone":"01020001087"},{"role":"مدير فرع طنطا الاستاد","name":"منة الله خالد","phone":"01013834861"},{"role":"مدير فرع طنطا سعيد","name":"رزان","phone":"01554527149"},{"role":"مدير فرع كفر الشيخ","name":"هدير","phone":"01020001087"},{"role":"مدير فرع شبين الكوم","name":"نغم فوزي","phone":"01012976405"},{"role":"الدعم الفني (IT)","name":"أحمد جمال","phone":"01064441486"}]'::jsonb, 13);
insert into public.kb_articles (slug, kind, title, body, sort) values ('manual:qa_scorecard', 'manual', 'QA_SCORECARD', '[{"item":"الترحيب والتعريف","weight":"١٠","req":"ترحيب دافي، اسم الشركة واسمك، تعريف العميل."},{"item":"الاستماع والاستكشاف","weight":"١٥","req":"من غير مقاطعة، إعادة صياغة، أسئلة مفتوحة ثم مغلقة."},{"item":"الدقة والحدود الطبية والسرية","weight":"٢٥","req":"معلومات صحيحة، من غير وعود أو نصائح طبية، تحقق من الهوية."},{"item":"التعاطف والنبرة","weight":"١٥","req":"اعتراف بالإحساس، نبرة دافية وهادية، من غير حشو."},{"item":"الحل والخطوة التالية","weight":"١٥","req":"طلب العميل اتحل أو تصعّد بشكل صحيح، وفي Next Step واضح."},{"item":"التوثيق","weight":"١٠","req":"تسجيل كامل وواضح في السيستم بالـ Tag الصح."},{"item":"الإغلاق","weight":"١٠","req":"خلاصة + «في حاجة تانية؟» + ختام لطيف."}]'::jsonb, 14);
insert into public.kb_articles (slug, kind, title, body, sort) values ('manual:critical_errors', 'manual', 'CRITICAL_ERRORS', '["وعد بنتيجة مضمونة أو نصيحة طبية أو تشخيص أو توجيه بدوا.","إفشاء بيانات عميل أو تأكيد بيانات لشخص غير مصرح.","تجاهل Red Flag أو تأخير التصعيد.","إساءة أو سخرية أو رد بنفس الأسلوب على عميل.","اختلاق سعر أو معلومة أو عرض.","إغلاق مكالمة فيها أعراض من غير Next Step وتصعيد."]'::jsonb, 15);
insert into public.kb_articles (slug, kind, title, body, sort) values ('manual:kpis', 'manual', 'KPIS', '[{"k":"AHT — متوسط زمن المكالمة","v":"الوقت من الرد لحد ما توثّق","note":"ما يبقاش على حساب الأمان أو التعاطف"},{"k":"FCR — الحل من أول مكالمة","v":"نسبة المشاكل اللي اتحلت من غير ما العميل يتصل تاني","note":"الأهم للثقة"},{"k":"CSAT — رضا العميل","v":"تقييم العميل للمكالمة","note":"بيتأثر بالتعاطف أكتر من السرعة"},{"k":"Booking Conversion","v":"نسبة الاستفسارات اللي اتحولت لحجز","note":"من غير ضغط أو عروض مزيفة"},{"k":"Abandon Rate","v":"نسبة اللي قفلوا قبل ما حد يرد","note":"مرتبط بالتزامك بجدولك (Adherence)"},{"k":"Adherence","v":"التزامك بمواعيد الشيفت والراحات","note":"بيأثر على تغطية الفريق"},{"k":"Callback SLA","v":"نسبة الـ Callbacks اللي اتنفذت في ميعادها","note":"الـ Callback الفايت = شكوى"},{"k":"QA Score","v":"نتيجة تقييم الجودة","note":"الهدف ثابت ومعلن"}]'::jsonb, 16);
insert into public.kb_articles (slug, kind, title, body, sort) values ('manual:status_meanings', 'manual', 'STATUS_MEANINGS', '[{"s":"Open","m":"معاد للعميل اتحدد ولم يتم تأكيده"},{"s":"Confirmed","m":"تم تأكيد المعاد مع العميل"},{"s":"No show","m":"تواصلوا مع العميل ولم يتم الرد من جانبه"},{"s":"Canceled","m":"تم تواصل فعلي مع العميل وتم إلغاء المعاد"},{"s":"Wait list","m":"عميل طلب تغيير معاد ولسه محددش وقت معين بس"},{"s":"Check in","m":"العميل فعليًا في العيادة"},{"s":"Completed","m":"العميل خلص الجلسة ومشى من العيادة"}]'::jsonb, 17);
insert into public.kb_articles (slug, kind, title, body, sort) values ('manual:glossary', 'manual', 'GLOSSARY', '[{"t":"Consultation","m":"استشارة مع الدكتور قبل أي إجراء."},{"t":"Informed Consent","m":"نموذج الموافقة المسبقة بعد شرح الخدمة والمخاطر للعميل."},{"t":"Follow-up","m":"متابعة بعد الجلسة أو بعد المكالمة."},{"t":"No-show","m":"عميل حجز ومحضرش ومحدش بلّغ."},{"t":"Escalation","m":"رفع الموضوع لمسؤول أعلى أو مختص."},{"t":"Warm Transfer","m":"تحويل المكالمة مع تلخيصها للمستلم."},{"t":"Callback","m":"مكالمة راجعة للعميل بميعاد متفق عليه."},{"t":"Red Flag","m":"علامة خطر تستدعي تصعيد أو طوارئ فورًا."},{"t":"Teach-back","m":"تطلب من العميل يكرر التعليمات علشان تتأكد إنه فهم."},{"t":"AHT / FCR / CSAT","m":"زمن المكالمة / الحل من أول مرة / رضا العميل."},{"t":"SLA","m":"المدة المتفق عليها لتنفيذ أو رد."}]'::jsonb, 18);
insert into public.kb_articles (slug, kind, title, body, sort) values ('manual:filler_brand_notes', 'manual', 'FILLER_BRAND_NOTES', '[{"match":"Calcium Filler","note":"رينج السعر من ١٢٬٠٠٠ إلى ١٤٬٠٠٠ جنيه."},{"match":"Jeuvederm","note":"رينج السعر من ٤٢٠٠ إلى ٨٨٠٠ جنيه."},{"match":"Cytosial","note":"السعر يبدأ من ٧٥٠٠ جنيه."},{"match":"Restylane","note":"رينج السعر من ٨٠٠٠ إلى ٨٨٠٠ جنيه."},{"match":"Stylage","note":"رينج السعر من ٧٥٠٠ إلى ٨٠٠٠ جنيه."},{"match":"Teosyal","note":"رينج السعر من ٩٠٠٠ إلى ١٠٬٠٠٠ جنيه."},{"match":"Xela","note":"السعر حوالي ٥٥٠٠ جنيه."},{"match":"Skinfill","note":"السعر حوالي ٦٥٠٠ جنيه."},{"match":"AQ Prodefine","note":"السعر حوالي ٧٥٠٠ جنيه."},{"match":"Neauvia","note":"رينج السعر من ٧٥٠٠ إلى ٨٠٠٠ جنيه."},{"match":"Croma","note":"السعر حوالي ٦٨٠٠ جنيه."}]'::jsonb, 19);
